                ChantScorePart(file: "chant-regina-caeli-solemne", caption: "Regina caeli", aspectRatio: 1.8462),
                ChantScorePart(file: "chant-vers-alt-gaude-et-laetare", caption: "Gaude et laetare", aspectRatio: 3.9357),
                ChantScorePart(file: "chant-or-deus-qui-per-web", caption: "Oremus. Deus qui per resurrectionem", aspectRatio: 1.8735)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/regina-caeli-solemne/")!,
            lines: [
                ChantLine(latin: "Regína cæli lætáre,", english: "O Queen of heaven, rejoice,", start: 0.41, end: 12.49),
                ChantLine(latin: "allelúia:", english: "alleluia.", start: 12.49, end: 16.72),
                ChantLine(latin: "Quia quem meruísti portáre,", english: "For He whom thou didst merit to bear,", start: 16.87, end: 39.06),
                ChantLine(latin: "allelúia:", english: "alleluia,", start: 39.09, end: 46.36),
                ChantLine(latin: "Resurréxit, sicut dixit, allelúia:", english: "hath risen, as He said, alleluia.", start: 46.91, end: 61.02),
                ChantLine(latin: "Ora pro nobis Deum,", english: "Pray for us to God,", start: 61.13, end: 68.38),
                ChantLine(latin: "allelúia.", english: "alleluia.", start: 68.55, end: 93.94),
                ChantLine(latin: "Gaude et lætáre, Virgo María, allelúia.", english: "Rejoice and be glad, O Virgin Mary, alleluia.", start: 95.61, end: 101.21),
                ChantLine(latin: "Quia surréxit Dóminus vere, allelúia.", english: "For the Lord is truly risen, alleluia.", start: 101.21, end: 107.01),
                ChantLine(latin: "Orémus. Deus, qui per resurrectiónem Fílii tui Dómini nostri Jesu Christi mundum lætificáre dignátus es:", english: "Let us pray. O God, who by the Resurrection of Thy Son, our Lord Jesus Christ, didst vouchsafe to give joy to the world;", start: 107.01, end: 118.55),
                ChantLine(latin: "præsta, quǽsumus; ut per ejus Genitrícem Vírginem Maríam perpétuæ capiámus gáudia vitæ.", english: "grant, we beseech Thee, that through His Mother, the Virgin Mary, we may obtain the joys of everlasting life.", start: 118.55, end: 130.58),
                ChantLine(latin: "Per eumdem Christum Dóminum nostrum.", english: "Through the same Christ our Lord.", start: 130.69, end: 136.56),
                ChantLine(latin: "Amen.", english: "Amen.", start: 136.61, end: 141.20)
            ]
        ),
        Chant(
            id: "sub_tuum",
            groupID: "ourLady",
            latinTitle: "Sub Tuum Præsidium",
            englishTitle: "We Fly to Thy Patronage",
            setting: nil,
            detail: "The oldest prayer to Mary that survives",
            prayerIDs: ["sub_tuum"],
            duration: 104.1,
            score: [
                ChantScorePart(file: "chant-sub-tuum-praesidium", caption: "Sub tuum praesidium", aspectRatio: 2.3434),
                ChantScorePart(file: "chant-vers-alt-ora-pro-nobis", caption: "Ora pro nobis", aspectRatio: 3.9357),
                ChantScorePart(file: "chant-or-concede-nos-famulos", caption: "Oremus. Concede nos famulos tuos", aspectRatio: 1.9268)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/sub-tuum-praesidium/")!,
            lines: [
                ChantLine(latin: "Sub tuum præsídium confúgimus,", english: "We fly to thy patronage,", start: 0.47, end: 7.17),
                ChantLine(latin: "sancta Dei Génitrix:", english: "O holy Mother of God;", start: 7.17, end: 12.07),
                ChantLine(latin: "nostras deprecatiónes ne despícias in necessitátibus:", english: "despise not our petitions in our necessities,", start: 12.07, end: 26.33),
                ChantLine(latin: "sed a perículis cunctis líbera nos semper, Virgo gloriósa et benedícta.", english: "but deliver us always from all dangers, O glorious and blessed Virgin.", start: 26.33, end: 49.80),
                ChantLine(latin: "Ora pro nobis, sancta Dei Génitrix.", english: "Pray for us, O holy Mother of God.", start: 52.29, end: 57.17),
                ChantLine(latin: "Ut digni efficiámur promissiónibus Christi.", english: "That we may be made worthy of the promises of Christ.", start: 57.17, end: 63.19),
                ChantLine(latin: "Orémus.", english: "Let us pray.", start: 63.19, end: 66.43),
                ChantLine(latin: "Concéde nos fámulos tuos, quǽsumus Dómine Deus, perpétua mentis et córporis sanitáte gaudére:", english: "Grant, we beseech Thee, O Lord God, unto us Thy servants, that we may rejoice in continual health of mind and body,", start: 66.43, end: 75.57),
                ChantLine(latin: "et gloriósa beátæ Maríæ semper Vírginis intercessióne,", english: "and by the glorious intercession of Blessed Mary, ever virgin,", start: 75.57, end: 81.81),
                ChantLine(latin: "a præsénti liberári tristítia, et ætérna pérfrui lætítia.", english: "may be delivered from present sadness, and enter into the joy of Thine eternal gladness.", start: 81.81, end: 89.47),
                ChantLine(latin: "Per Christum Dóminum nostrum.", english: "Through Christ our Lord.", start: 89.47, end: 94.57),
                ChantLine(latin: "Amen.", english: "Amen.", start: 94.57, end: 99.96)
            ]
        ),
        Chant(
            id: "ave_maris_stella",
            groupID: "ourLady",
            latinTitle: "Ave Maris Stella",
            englishTitle: "Hail, Star of the Sea",
            setting: nil,
            detail: "The evening hymn of her feasts and of her Saturdays",
            prayerIDs: ["ave_maris_stella"],
            duration: 132.0,
            score: [
                ChantScorePart(file: "chant-ave-maris-stella-off-bmv-in-sabb", caption: "Ave maris stella", aspectRatio: 0.8081)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/ave-maris-stella-off-bmv-in-sabb/")!,
            lines: [
                ChantLine(latin: "Ave maris stella, Dei Mater alma,", english: "Hail, O Star of the ocean, God's own Mother blest,", start: 0.25, end: 7.65),
                ChantLine(latin: "atque semper Virgo, felix cæli porta.", english: "ever sinless Virgin, gate of heavenly rest.", start: 7.65, end: 15.56),
                ChantLine(latin: "Sumens illud Ave Gabriélis ore,", english: "Taking that sweet Ave, which from Gabriel came,", start: 16.85, end: 24.49),
                ChantLine(latin: "Funda nos in pace, Mutans Hevæ nomen.", english: "peace confirm within us, changing Eve's name.", start: 24.49, end: 32.48),
                ChantLine(latin: "Solve vincla reis, Profer lumen cæcis", english: "Break the sinners' fetters, make our blindness day,", start: 33.69, end: 41.23),
                ChantLine(latin: "Mala nostra pelle, Bona cuncta posce.", english: "chase all evils from us, for all blessings pray.", start: 41.23, end: 49.30),
                ChantLine(latin: "Monstra te esse matrem: Sumat per te preces,", english: "Show thyself a Mother, may the Word divine", start: 50.75, end: 58.57),
                ChantLine(latin: "Qui pro nobis natus, Tulit esse tuus.", english: "born for us thine Infant hear our prayers through thine.", start: 58.57, end: 66.68),
                ChantLine(latin: "Virgo singuláris, Inter omnes mitis,", english: "Virgin all excelling, mildest of the mild,", start: 67.99, end: 75.75),
                ChantLine(latin: "Nos culpis solútos, Mitis fac et castos.", english: "free from guilt preserve us meek and undefiled.", start: 75.75, end: 84.50),
                ChantLine(latin: "Vitam præsta puram, Iter para tutum:", english: "Keep our life all spotless, make our way secure", start: 85.47, end: 93.19),
                ChantLine(latin: "Ut vidéntes Jesum Semper collætémur.", english: "till we find in Jesus, joy for evermore.", start: 93.19, end: 101.38),
                ChantLine(latin: "Sit laus Deo Patri, Summo Christo decus,", english: "Praise to God the Father, honor to the Son,", start: 102.77, end: 110.35),
                ChantLine(latin: "Spirítui Sancto, Tribus honor unus.", english: "in the Holy Spirit, be the glory one.", start: 110.35, end: 118.98),
                ChantLine(latin: "Amen.", english: "Amen.", start: 120.15, end: 127.18)
            ]
        ),
        Chant(
            id: "magnificat",
            groupID: "ourLady",
            latinTitle: "Magnificat",
            englishTitle: "The Canticle of Mary",
            setting: "With alleluia",
            detail: "Mary's own song, sung at evening prayer every day",
            prayerIDs: ["magnificat"],
            duration: 314.1,
            score: [
                ChantScorePart(file: "chant-magnificat-cum-alleluia", caption: "Magnificat cum Alleluia", aspectRatio: 0.2752)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/magnificat-cum-alleluia/")!,
            lines: [
                ChantLine(latin: "Allelúia: Allelúia, allelúia.", english: "Alleluia: alleluia, alleluia.", start: 0.27, end: 10.74),
                ChantLine(latin: "Allelúia: Allelúia, allelúia.", english: "Alleluia: alleluia, alleluia.", start: 11.19, end: 21.82),
                ChantLine(latin: "Magníficat ánima mea Dóminum.", english: "My soul doth magnify the Lord.", start: 22.59, end: 30.59),
                ChantLine(latin: "Allelúia, allelúia.", english: "Alleluia, alleluia.", start: 30.59, end: 37.46),
                ChantLine(latin: "Et exsultávit spíritus meus in Deo salutári meo.", english: "And my spirit hath rejoiced in God my Saviour.", start: 38.01, end: 51.78),
                ChantLine(latin: "Allelúia: Allelúia, allelúia.", english: "Alleluia: alleluia, alleluia.", start: 52.17, end: 62.60),
                ChantLine(latin: "Quia respéxit humilitátem ancíllæ suæ:", english: "Because He hath regarded the humility of His handmaid:", start: 63.17, end: 69.91),
                ChantLine(latin: "ecce enim ex hoc beátam me dicent omnes generatiónes.", english: "for behold from henceforth all generations shall call me blessed.", start: 69.91, end: 79.29),
                ChantLine(latin: "Allelúia, allelúia.", english: "Alleluia, alleluia.", start: 79.29, end: 86.72),
                ChantLine(latin: "Quia fecit mihi magna qui potens est:", english: "Because He that is mighty hath done great things to me:", start: 87.17, end: 94.17),
                ChantLine(latin: "et sanctum nomen ejus.", english: "and holy is His name.", start: 94.17, end: 100.74),
                ChantLine(latin: "Allelúia: Allelúia, allelúia.", english: "Alleluia: alleluia, alleluia.", start: 101.29, end: 112.08),
                ChantLine(latin: "Et misericórdia ejus a progénie in progénies", english: "And His mercy is from generation unto generations,", start: 112.47, end: 121.08),
                ChantLine(latin: "timéntibus eum.", english: "to them that fear Him.", start: 121.13, end: 125.65),
                ChantLine(latin: "Allelúia, allelúia.", english: "Alleluia, alleluia.", start: 125.65, end: 132.88),
                ChantLine(latin: "Fecit poténtiam in bráchio suo: dispérsit supérbos mente cordis sui.", english: "He hath shewed might in His arm: He hath scattered the proud in the conceit of their heart.", start: 133.37, end: 147.98),
                ChantLine(latin: "Allelúia: Allelúia, allelúia.", english: "Alleluia: alleluia, alleluia.", start: 148.59, end: 158.92),
                ChantLine(latin: "Depósuit poténtes de sede, et exaltávit húmiles.", english: "He hath put down the mighty from their seat, and hath exalted the humble.", start: 159.77, end: 170.61),
                ChantLine(latin: "Allelúia, allelúia.", english: "Alleluia, alleluia.", start: 170.61, end: 177.98),
                ChantLine(latin: "Esuriéntes implévit bonis:", english: "He hath filled the hungry with good things:", start: 178.47, end: 184.77),
                ChantLine(latin: "et dívites dimísit inánes.", english: "and the rich He hath sent empty away.", start: 184.77, end: 191.98),
                ChantLine(latin: "Allelúia: Allelúia, allelúia.", english: "Alleluia: alleluia, alleluia.", start: 192.41, end: 202.98),
                ChantLine(latin: "Suscépit Israël púerum suum:", english: "He hath received Israel His servant,", start: 203.85, end: 209.75),
                ChantLine(latin: "recordátus misericórdiæ suæ.", english: "being mindful of His mercy.", start: 209.75, end: 216.03),
                ChantLine(latin: "Allelúia, allelúia.", english: "Alleluia, alleluia.", start: 216.03, end: 222.82),
                ChantLine(latin: "Sicut locútus est ad patres nostros,", english: "As He spoke to our fathers,", start: 223.95, end: 230.71),
                ChantLine(latin: "Abraham et sémini ejus in sǽcula.", english: "to Abraham and to his seed for ever.", start: 230.71, end: 239.26),
                ChantLine(latin: "Allelúia: Allelúia, allelúia.", english: "Alleluia: alleluia, alleluia.", start: 239.87, end: 250.36),
                ChantLine(latin: "Glória Patri, et Fílio,", english: "Glory be to the Father, and to the Son,", start: 250.93, end: 256.33),
                ChantLine(latin: "et Spirítui Sancto.", english: "and to the Holy Spirit.", start: 256.33, end: 261.25),
                ChantLine(latin: "Allelúia, allelúia.", english: "Alleluia, alleluia.", start: 261.25, end: 268.20),
                ChantLine(latin: "Sicut erat in princípio, et nunc, et semper,", english: "As it was in the beginning, is now, and ever shall be,", start: 268.89, end: 277.51),
                ChantLine(latin: "et in sǽcula sæculórum. Amen.", english: "world without end. Amen.", start: 277.51, end: 285.32),
                ChantLine(latin: "Allelúia: Allelúia, allelúia.", english: "Alleluia: alleluia, alleluia.", start: 286.01, end: 296.86),
                ChantLine(latin: "Allelúia: Allelúia, allelúia.", english: "Alleluia: alleluia, alleluia.", start: 297.53, end: 309.72)
            ]
        ),
        Chant(
