            groupID: "ourLady",
            latinTitle: "Tota Pulchra Es",
            englishTitle: "Thou Art All Fair",
            setting: nil,
            detail: "In honour of the Immaculate Conception: Mary, conceived without sin",
            prayerIDs: ["tota_pulchra"],
            duration: 108.0,
            score: [
                ChantScorePart(file: "chant-tota-pulchra-es-maria-web", caption: "Tota pulchra es Maria", aspectRatio: 1.1321)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/tota-pulchra-es-maria/")!,
            lines: [
                ChantLine(latin: "Tota pulchra es, María!", english: "Thou art all fair, O Mary,", start: 0.45, end: 7.58),
                ChantLine(latin: "Tota pulchra es, María!", english: "thou art all fair, O Mary,", start: 7.65, end: 14.33),
                ChantLine(latin: "Et mácula originális non est in te.", english: "and the original stain is not in thee.", start: 14.33, end: 22.65),
                ChantLine(latin: "Et mácula originális non est in te.", english: "and the original stain is not in thee.", start: 22.65, end: 31.72),
                ChantLine(latin: "Tu, glória Jerúsalem.", english: "Thou art the glory of Jerusalem,", start: 32.49, end: 39.11),
                ChantLine(latin: "Tu, lætítia Israël.", english: "thou art the joy of Israel,", start: 39.11, end: 46.44),
                ChantLine(latin: "Tu, honorificéntia pópuli nostri.", english: "thou art the honour of our people,", start: 46.59, end: 54.44),
                ChantLine(latin: "Tu, advocáta peccatórum.", english: "thou art the advocate of sinners.", start: 54.95, end: 62.24),
                ChantLine(latin: "O María! O María!", english: "O Mary, O Mary,", start: 62.49, end: 73.55),
                ChantLine(latin: "Virgo prudentíssima!", english: "Virgin most prudent,", start: 73.55, end: 79.03),
                ChantLine(latin: "Mater clementíssima!", english: "Mother most merciful,", start: 79.03, end: 84.22),
                ChantLine(latin: "Ora pro nobis.", english: "pray for us,", start: 84.49, end: 89.89),
                ChantLine(latin: "Intercéde pro nobis", english: "intercede for us", start: 89.89, end: 94.51),
                ChantLine(latin: "ad Dóminum Jesum Christum.", english: "with our Lord Jesus Christ.", start: 94.51, end: 102.88)
            ]
        ),
        Chant(
            id: "flos_carmeli",
            groupID: "ourLady",
            latinTitle: "Flos Carmeli",
            englishTitle: "Flower of Carmel",
            setting: nil,
            detail: "The feast poem of Our Lady of Mount Carmel",
            prayerIDs: ["flos_carmeli"],
            duration: 168.0,
            score: [
                ChantScorePart(file: "chant-flos-carmeli-w", caption: "Flos Carmeli", aspectRatio: 0.7470)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/flos-carmeli/")!,
            lines: [
                ChantLine(latin: "Flos Carméli, vitis florígera,", english: "Flower of Carmel, vine in blossom,", start: 0.47, end: 6.36),
                ChantLine(latin: "splendor cæli,", english: "splendour of heaven,", start: 6.55, end: 9.35),
                ChantLine(latin: "Virgo puérpera", english: "Virgin who didst bear a Son,", start: 9.37, end: 13.09),
                ChantLine(latin: "singuláris.", english: "none like to thee.", start: 13.09, end: 16.10),
                ChantLine(latin: "Mater mitis,", english: "Mother most gentle,", start: 17.27, end: 20.83),
                ChantLine(latin: "sed viri néscia,", english: "who knewest not man,", start: 20.83, end: 24.39),
                ChantLine(latin: "Carmelítis", english: "to thy Carmelites", start: 24.39, end: 27.93),
                ChantLine(latin: "esto propítia,", english: "be thou gracious,", start: 27.93, end: 31.77),
                ChantLine(latin: "Stella maris.", english: "O Star of the Sea.", start: 31.77, end: 36.16),
                ChantLine(latin: "Radix Jesse", english: "Root of Jesse,", start: 37.89, end: 40.99),
                ChantLine(latin: "gérminans flósculum,", english: "putting forth a little flower,", start: 40.99, end: 44.18),
                ChantLine(latin: "nos adésse", english: "that we may be", start: 44.73, end: 47.65),
                ChantLine(latin: "tecum in sǽculum", english: "with thee for ever", start: 47.65, end: 51.30),
                ChantLine(latin: "patiáris.", english: "do thou permit.", start: 51.41, end: 54.36),
                ChantLine(latin: "Inter spinas", english: "Thou who among thorns", start: 55.73, end: 59.33),
                ChantLine(latin: "quæ crescis lílium,", english: "growest as a lily,", start: 59.33, end: 63.17),
                ChantLine(latin: "serva puras", english: "keep pure", start: 63.17, end: 66.73),
                ChantLine(latin: "mentes fragílium,", english: "the minds of the frail,", start: 66.73, end: 70.55),
                ChantLine(latin: "tuteláris.", english: "as their guardian.", start: 70.55, end: 75.18),
                ChantLine(latin: "Armatúra", english: "O armour", start: 76.99, end: 79.99),
                ChantLine(latin: "fortis pugnántium,", english: "strong for them that fight,", start: 79.99, end: 83.20),
                ChantLine(latin: "furunt bella,", english: "the wars rage:", start: 83.69, end: 86.47),
                ChantLine(latin: "tende præsídium", english: "hold forth as a defence", start: 86.47, end: 89.78),
                ChantLine(latin: "Scapuláris.", english: "the Scapular.", start: 90.43, end: 93.56),
                ChantLine(latin: "Per incérta", english: "Through things uncertain", start: 95.15, end: 98.61),
                ChantLine(latin: "prudens consílium,", english: "prudent counsel,", start: 98.61, end: 102.27),
                ChantLine(latin: "per advérsa", english: "through adversity", start: 102.27, end: 105.71),
                ChantLine(latin: "juge solátium", english: "unfailing comfort", start: 105.72, end: 109.47),
                ChantLine(latin: "largiáris.", english: "do thou bestow.", start: 109.47, end: 113.96),
                ChantLine(latin: "Mater dulcis", english: "Sweet Mother,", start: 115.89, end: 118.88),
                ChantLine(latin: "Carméli dómina,", english: "Lady of Carmel,", start: 119.03, end: 122.42),
                ChantLine(latin: "plebem tuam", english: "thy people", start: 122.65, end: 125.71),
                ChantLine(latin: "reple lætítia", english: "fill with the gladness", start: 125.71, end: 129.48),
                ChantLine(latin: "qua beáris.", english: "wherewith thou art blessed.", start: 129.65, end: 132.68),
                ChantLine(latin: "Paradísi", english: "Of Paradise", start: 134.05, end: 137.45),
                ChantLine(latin: "clavis et jánua,", english: "the key and the gate,", start: 137.45, end: 141.27),
                ChantLine(latin: "fac nos duci", english: "cause us to be led", start: 141.27, end: 144.83),
                ChantLine(latin: "quo, Mater, glória", english: "whither, O Mother, with glory", start: 144.83, end: 148.55),
                ChantLine(latin: "coronáris.", english: "thou art crowned.", start: 148.55, end: 153.34),
                ChantLine(latin: "Amen. Allelúia.", english: "Amen. Alleluia.", start: 154.87, end: 163.28)
            ]
        ),
        Chant(
            id: "stabat_mater",
            groupID: "ourLady",
            latinTitle: "Stabat Mater",
            englishTitle: "The Mother Stood",
            setting: "Feast poem",
            detail: "The feast poem of the Seven Sorrows of Mary",
            prayerIDs: ["stabat_mater"],
            duration: 330.0,
            score: [
                ChantScorePart(file: "chant-stabat-mater-seq", caption: "Stabat Mater", aspectRatio: 0.3278)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/stabat-mater-sequentia/")!,
            lines: [
                ChantLine(latin: "Stabat Mater dolorósa", english: "The Mother stood in sorrow,", start: 0.51, end: 5.39),
                ChantLine(latin: "Juxta crucem lacrimósa,", english: "weeping beside the Cross", start: 5.39, end: 10.27),
                ChantLine(latin: "Dum pendébat Fílius.", english: "whereon her Son was hanging.", start: 10.27, end: 14.66),
                ChantLine(latin: "Cujus ánimam geméntem,", english: "Through her soul, lamenting,", start: 15.41, end: 20.53),
                ChantLine(latin: "Contristátam et doléntem,", english: "saddened and grieving,", start: 20.53, end: 25.73),
                ChantLine(latin: "Pertransívit gládius.", english: "the sword hath passed.", start: 25.73, end: 30.18),
                ChantLine(latin: "O quam tristis et afflícta", english: "O how sad and how afflicted", start: 30.99, end: 36.15),
                ChantLine(latin: "Fuit illa benedícta", english: "was that blessed one,", start: 36.15, end: 41.05),
                ChantLine(latin: "Mater Unigéniti!", english: "the Mother of the Only-begotten.", start: 41.05, end: 45.96),
                ChantLine(latin: "Quæ mærébat et dolébat,", english: "She mourned and she grieved,", start: 46.35, end: 51.43),
                ChantLine(latin: "Pia Mater, dum vidébat", english: "the loving Mother, as she beheld", start: 51.43, end: 56.49),
                ChantLine(latin: "Nati pœnas ínclyti.", english: "the torments of her glorious Son.", start: 56.49, end: 61.44),
                ChantLine(latin: "Quis est homo qui non fleret,", english: "Who is the man that would not weep", start: 61.97, end: 67.07),
                ChantLine(latin: "Matrem Christi si vidéret", english: "if he should see the Mother of Christ", start: 67.07, end: 72.47),
                ChantLine(latin: "In tanto supplício?", english: "in so great anguish?", start: 72.47, end: 77.60),
                ChantLine(latin: "Quis non posset contristári,", english: "Who could keep from sorrow,", start: 77.67, end: 82.73),
                ChantLine(latin: "Christi Matrem contemplári", english: "beholding the Mother of Christ", start: 82.74, end: 88.05),
                ChantLine(latin: "Doléntem cum Fílio?", english: "grieving with her Son?", start: 88.05, end: 92.68),
                ChantLine(latin: "Pro peccátis suæ gentis", english: "For the sins of His own people", start: 93.29, end: 98.75),
                ChantLine(latin: "Vidit Jesum in torméntis,", english: "she saw Jesus in torments,", start: 98.75, end: 103.84),
                ChantLine(latin: "Et flagéllis súbditum.", english: "and given over to the scourge.", start: 104.03, end: 109.14),
                ChantLine(latin: "Vidit suum dulcem natum", english: "She saw her own sweet Son", start: 109.51, end: 115.03),
                ChantLine(latin: "Moriéndo desolátum,", english: "forsaken in His dying,", start: 115.03, end: 120.47),
                ChantLine(latin: "Dum emísit spíritum.", english: "as He gave up His spirit.", start: 120.47, end: 125.52),
                ChantLine(latin: "Eia Mater, fons amóris,", english: "O Mother, fount of love,", start: 126.11, end: 131.42),
                ChantLine(latin: "Me sentíre vim dolóris", english: "let me feel the force of thy sorrow,", start: 131.47, end: 136.81),
                ChantLine(latin: "Fac, ut tecum lúgeam.", english: "make me mourn with thee.", start: 136.81, end: 142.02),
                ChantLine(latin: "Fac ut árdeat cor meum", english: "Make my heart to burn", start: 142.37, end: 147.51),
                ChantLine(latin: "In amándo Christum Deum,", english: "in loving Christ my God,", start: 147.51, end: 152.75),
                ChantLine(latin: "Ut sibi compláceam.", english: "that I may be pleasing to Him.", start: 152.75, end: 158.01),
                ChantLine(latin: "Sancta Mater, istud agas,", english: "Holy Mother, do this for me:", start: 158.01, end: 163.03),
                ChantLine(latin: "Crucifíxi fige plagas", english: "fix the wounds of the Crucified", start: 163.03, end: 168.15),
                ChantLine(latin: "Cordi meo válide.", english: "deep within my heart.", start: 168.15, end: 172.90),
                ChantLine(latin: "Tui nati vulneráti,", english: "Of thy wounded Son,", start: 173.35, end: 178.29),
                ChantLine(latin: "Tam dignáti pro me pati,", english: "Who deigned to suffer so much for me,", start: 178.29, end: 183.43),
                ChantLine(latin: "Pœnas mecum dívide.", english: "share with me the pains.", start: 183.43, end: 188.64),
                ChantLine(latin: "Fac me tecum pie flere,", english: "Let me weep with thee in love,", start: 188.95, end: 194.03),
                ChantLine(latin: "Crucifíxo condolére,", english: "and grieve with the Crucified,", start: 194.03, end: 199.33),
                ChantLine(latin: "Donec ego víxero.", english: "as long as I shall live.", start: 199.33, end: 204.63),
                ChantLine(latin: "Juxta crucem tecum stare,", english: "To stand beside the Cross with thee,", start: 204.63, end: 209.75),
                ChantLine(latin: "Et me tibi sociáre", english: "and to join myself to thee", start: 209.75, end: 215.13),
                ChantLine(latin: "In planctu desídero.", english: "in lamenting, is my desire.", start: 215.13, end: 220.18),
                ChantLine(latin: "Virgo vírginum præclára,", english: "Virgin, most glorious of virgins,", start: 220.47, end: 225.89),
                ChantLine(latin: "Mihi jam non sis amára:", english: "be not bitter to me now;", start: 225.89, end: 231.21),
                ChantLine(latin: "Fac me tecum plángere.", english: "let me lament with thee.", start: 231.21, end: 235.78),
                ChantLine(latin: "Fac ut portem Christi mortem,", english: "Let me bear the death of Christ,", start: 236.75, end: 242.11),
                ChantLine(latin: "Passiónis fac consórtem,", english: "make me a sharer in His Passion,", start: 242.11, end: 247.39),
                ChantLine(latin: "Et plagas recólere.", english: "and keep His wounds in mind.", start: 247.39, end: 252.40),
                ChantLine(latin: "Fac me plagis vulnerári,", english: "Let me be wounded with His wounds,", start: 252.89, end: 257.95),
                ChantLine(latin: "Fac me cruce inebriári,", english: "let me be inebriated with the Cross", start: 257.95, end: 263.03),
                ChantLine(latin: "Et cruóre Fílii.", english: "and with the Blood of thy Son.", start: 263.03, end: 268.12),
                ChantLine(latin: "Flammis ne urar succénsus,", english: "Lest I burn, enkindled by the flames,", start: 268.53, end: 273.83),
                ChantLine(latin: "Per te, Virgo, sim defénsus", english: "by thee, O Virgin, may I be defended", start: 273.83, end: 279.07),
                ChantLine(latin: "In die judícii.", english: "in the day of judgement.", start: 279.07, end: 283.78),
                ChantLine(latin: "Christe, cum sit hinc exíre,", english: "O Christ, when I must go from hence,", start: 284.55, end: 289.55),
                ChantLine(latin: "Da per Matrem me veníre", english: "grant that through Thy Mother I may come", start: 289.55, end: 294.89),
                ChantLine(latin: "Ad palmam victóriæ.", english: "to the palm of victory.", start: 294.89, end: 299.98),
                ChantLine(latin: "Quando corpus moriétur,", english: "When my body dies,", start: 300.41, end: 305.65),
                ChantLine(latin: "Fac ut ánimæ donétur", english: "grant that to my soul be given", start: 305.65, end: 310.83),
                ChantLine(latin: "Paradísi glória.", english: "the glory of paradise.", start: 310.83, end: 316.56),
                ChantLine(latin: "Amen. Allelúia.", english: "Amen. Alleluia.", start: 316.95, end: 325.62)
