            lines: [
                ChantLine(latin: "Ave María, grátia plena, Dóminus tecum,", english: "Hail Mary, full of grace, the Lord is with thee;", start: 0.27, end: 12.53),
                ChantLine(latin: "benedícta tu in muliéribus,", english: "blessed art thou among women,", start: 12.53, end: 20.49),
                ChantLine(latin: "et benedíctus fructus ventris tui, Jesus.", english: "and blessed is the fruit of thy womb, Jesus.", start: 20.49, end: 29.90),
                ChantLine(latin: "Sancta María, Mater Dei,", english: "Holy Mary, Mother of God,", start: 30.17, end: 36.65),
                ChantLine(latin: "ora pro nobis peccatóribus,", english: "pray for us sinners,", start: 36.65, end: 43.53),
                ChantLine(latin: "nunc et in hora mortis nostræ. Amen.", english: "now and at the hour of our death. Amen.", start: 43.53, end: 53.46)
            ]
        ),
        Chant(
            id: "salve_mater",
            groupID: "ourLady",
            latinTitle: "Salve Mater Misericordiæ",
            englishTitle: "Hail, Mother of Mercy",
            setting: nil,
            detail: "A hymn to Mary with a refrain for all to sing",
            prayerIDs: [],
            duration: 463.0,
            score: [
                ChantScorePart(file: "chant-salve-mater", caption: "Salve Mater", aspectRatio: 0.4119)
