            latinTitle: "Inviolata",
            englishTitle: "Inviolate",
            setting: nil,
            detail: "A hymn to Mary, ever a virgin",
            prayerIDs: [],
            duration: 90.0,
            score: [
                ChantScorePart(file: "chant-inviolata", caption: "Inviolata", aspectRatio: 1.4473)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/inviolata/")!,
            lines: [
                ChantLine(latin: "Invioláta, íntegra, et casta es María:", english: "Inviolate, spotless and chaste art thou, O Mary,", start: 0.29, end: 8.71),
                ChantLine(latin: "Quæ es effécta fúlgida cæli porta.", english: "who art made the shining gate of heaven.", start: 8.71, end: 14.83),
                ChantLine(latin: "O Mater alma Christi caríssima:", english: "O loving Mother of Christ, most dear,", start: 14.83, end: 20.67),
                ChantLine(latin: "Súscipe pia laudum præcónia.", english: "receive our loving songs of praise.", start: 20.67, end: 26.75),
                ChantLine(latin: "Te nunc flágitant devóta corda et ora:", english: "Devout hearts and lips now beseech thee", start: 26.75, end: 34.64),
                ChantLine(latin: "Nostra ut pura péctora sint et córpora.", english: "that our hearts and bodies may be pure.", start: 34.99, end: 43.02),
                ChantLine(latin: "Tua per precáta dulcísona:", english: "By thy sweet-sounding prayers", start: 43.13, end: 48.71),
                ChantLine(latin: "Nobis concédas véniam per sǽcula.", english: "grant us pardon for ever.", start: 48.71, end: 56.25),
                ChantLine(latin: "O benígna!", english: "O kindly one!", start: 56.25, end: 60.91),
                ChantLine(latin: "O Regína!", english: "O Queen!", start: 60.91, end: 65.75),
                ChantLine(latin: "O María!", english: "O Mary!", start: 65.75, end: 70.73),
                ChantLine(latin: "Quæ sola invioláta permansísti.", english: "who alone hast remained inviolate.", start: 70.73, end: 85.12)
            ]
        ),
        Chant(
            id: "o_gloriosa",
            groupID: "ourLady",
            latinTitle: "O Gloriosa Virginum",
            englishTitle: "O Glorious Virgin",
            setting: nil,
            detail: "The morning hymn of Mary's feasts",
            prayerIDs: [],
            duration: 119.1,
            score: [
                ChantScorePart(file: "chant-o-gloriosa-virginum", caption: "O gloriosa Virginum", aspectRatio: 1.1474)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/o-gloriosa-virginum/")!,
            lines: [
                ChantLine(latin: "O gloriósa Vírginum", english: "O glorious one among virgins,", start: 0.29, end: 6.93),
                ChantLine(latin: "Sublímis inter sídera:", english: "lofty among the stars,", start: 6.93, end: 12.61),
                ChantLine(latin: "Qui te creávit, párvulum", english: "Him who created thee, as a little Child,", start: 12.61, end: 19.23),
                ChantLine(latin: "Lacténte nutris úbere.", english: "thou dost nourish at thy breast.", start: 19.23, end: 25.28),
                ChantLine(latin: "Quod Heva tristis ábstulit,", english: "What sorrowful Eve took away,", start: 26.89, end: 33.69),
                ChantLine(latin: "Tu reddis almo gérmine:", english: "thou restorest through thy gracious Offspring;", start: 33.69, end: 39.44),
                ChantLine(latin: "Intrent ut astra flébiles,", english: "that those who weep may enter the stars,", start: 39.65, end: 46.43),
                ChantLine(latin: "Cæli reclúdis cárdines.", english: "thou openest the doors of heaven.", start: 46.43, end: 52.52),
                ChantLine(latin: "Tu Regis alti jánua,", english: "Thou art the gate of the King on high,", start: 54.19, end: 60.79),
                ChantLine(latin: "Et aula lucis fúlgida:", english: "and the shining hall of light:", start: 60.79, end: 66.53),
                ChantLine(latin: "Vitam datam per Vírginem,", english: "for the life given through the Virgin,", start: 66.53, end: 73.29),
                ChantLine(latin: "Gentes redémptæ, pláudite.", english: "ye redeemed nations, give praise.", start: 73.29, end: 80.14),
                ChantLine(latin: "Jesu, tibi sit glória,", english: "Jesus, to Thee be glory,", start: 81.25, end: 87.99),
                ChantLine(latin: "Qui natus es de Vírgine,", english: "Who wast born of the Virgin,", start: 87.99, end: 93.94),
                ChantLine(latin: "Cum Patre et almo Spíritu,", english: "with the Father and the gracious Spirit,", start: 93.95, end: 100.57),
                ChantLine(latin: "In sempitérna sǽcula.", english: "for everlasting ages.", start: 100.57, end: 107.64),
                ChantLine(latin: "Amen.", english: "Amen.", start: 108.21, end: 113.58)
            ]
        ),
        Chant(
