            sourceURL: URL(string: "https://www.verbumgloriae.es/project/adoro-te-devote/")!,
            lines: [
                ChantLine(latin: "Adóro te devóte, latens Déitas,", english: "I adore Thee devoutly, O hidden Deity,", start: 0.45, end: 8.91),
                ChantLine(latin: "Quæ sub his figúris vere látitas:", english: "Who under these figures art truly concealed;", start: 8.91, end: 17.37),
                ChantLine(latin: "Tibi se cor meum totum súbjicit,", english: "to Thee my whole heart subjects itself,", start: 17.37, end: 25.89),
                ChantLine(latin: "Quia te contémplans totum déficit.", english: "for in contemplating Thee it wholly fails.", start: 25.89, end: 34.74),
                ChantLine(latin: "Visus, tactus, gustus in te fállitur,", english: "Sight, touch and taste are deceived in Thee,", start: 36.07, end: 44.87),
                ChantLine(latin: "Sed audítu solo tuto créditur:", english: "but by hearing alone is it safely believed;", start: 44.87, end: 53.17),
                ChantLine(latin: "Credo quidquid dixit Dei Fílius:", english: "I believe whatever the Son of God has said:", start: 53.17, end: 61.66),
                ChantLine(latin: "Nil hoc verbo veritátis vérius.", english: "nothing is truer than this word of Truth.", start: 61.71, end: 69.34),
                ChantLine(latin: "In Cruce latébat sola Déitas,", english: "On the Cross the Godhead alone lay hidden,", start: 70.67, end: 79.15),
                ChantLine(latin: "At hic latet simul et humánitas:", english: "but here the manhood too lies hidden with it;", start: 79.15, end: 87.75),
                ChantLine(latin: "Ambo tamen credens atque cónfitens,", english: "yet believing and confessing both,", start: 87.75, end: 96.54),
                ChantLine(latin: "Peto quod petívit latro pǽnitens.", english: "I ask for what the penitent thief asked.", start: 96.63, end: 105.42),
                ChantLine(latin: "Plagas, sicut Thomas, non intúeor:", english: "I do not look upon the wounds, as Thomas did;", start: 106.55, end: 115.07),
                ChantLine(latin: "Deum tamen meum te confíteor:", english: "yet I confess Thee to be my God;", start: 115.07, end: 123.67),
                ChantLine(latin: "Fac me tibi semper magis crédere,", english: "make me ever more and more believe in Thee,", start: 123.67, end: 132.36),
                ChantLine(latin: "In te spem habére, te dilígere.", english: "have hope in Thee, and love Thee.", start: 132.49, end: 141.50),
                ChantLine(latin: "O memoriále mortis Dómini,", english: "O memorial of the death of the Lord,", start: 142.53, end: 151.01),
                ChantLine(latin: "Panis vivus vitam præstans hómini:", english: "living Bread that gives life to man,", start: 151.01, end: 159.75),
                ChantLine(latin: "Præsta meæ menti de te vívere,", english: "grant to my mind to live on Thee,", start: 159.75, end: 168.53),
                ChantLine(latin: "Et te illi semper dulce sápere.", english: "and that Thou be ever sweet to its taste.", start: 168.53, end: 177.86),
                ChantLine(latin: "Pie pellicáne, Jesu Dómine,", english: "O loving Pelican, Lord Jesus,", start: 179.13, end: 187.63),
                ChantLine(latin: "Me immúndum munda tuo Sánguine:", english: "cleanse me, who am unclean, with Thy Blood,", start: 187.63, end: 196.47),
                ChantLine(latin: "Cujus una stilla salvum fácere", english: "a single drop of which can make safe", start: 196.47, end: 204.92),
                ChantLine(latin: "Totum mundum quit ab omni scélere.", english: "the whole world from every sin.", start: 205.39, end: 213.22),
                ChantLine(latin: "Jesu, quem velátum nunc aspício,", english: "Jesus, Whom now I look upon veiled,", start: 214.35, end: 223.11),
                ChantLine(latin: "Oro fiat illud quod tam sítio:", english: "I pray that what I so thirst for may come to pass:", start: 223.11, end: 231.77),
                ChantLine(latin: "Ut te reveláta cernens fácie,", english: "that, seeing Thee with Thy face unveiled,", start: 231.77, end: 240.50),
                ChantLine(latin: "Visu sim beátus tuæ glóriæ.", english: "I may be blessed in beholding Thy glory.", start: 240.69, end: 249.66),
                ChantLine(latin: "Amen.", english: "Amen.", start: 251.21, end: 260.68)
            ]
        ),
        Chant(
            id: "ave_verum",
            groupID: "sacrament",
            latinTitle: "Ave Verum Corpus",
            englishTitle: "Hail, True Body",
            setting: nil,
            detail: "Sung as the priest raises the Host, and at Benediction",
            prayerIDs: ["ave_verum"],
            duration: 87.0,
            score: [
                ChantScorePart(file: "chant-ave-verum-corpus", caption: "Ave verum Corpus", aspectRatio: 1.7547)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/ave-verum-corpus/")!,
            lines: [
                ChantLine(latin: "Ave verum Corpus natum", english: "Hail, true Body, born", start: 0.27, end: 7.17),
                ChantLine(latin: "de María Vírgine:", english: "of the Virgin Mary,", start: 7.17, end: 12.86),
                ChantLine(latin: "Vere passum, immolátum in cruce pro hómine:", english: "that truly suffered and was sacrificed upon the cross for man;", start: 13.23, end: 26.60),
                ChantLine(latin: "Cujus latus perforátum", english: "Whose side, when it was pierced,", start: 26.81, end: 33.33),
                ChantLine(latin: "fluxit aqua et sánguine:", english: "flowed with water and with blood:", start: 33.33, end: 41.18),
                ChantLine(latin: "Esto nobis prægustátum", english: "be for us a foretaste", start: 41.49, end: 47.67),
                ChantLine(latin: "mortis in exámine.", english: "in the trial of death.", start: 47.68, end: 54.90),
                ChantLine(latin: "O Jesu dulcis!", english: "O sweet Jesus,", start: 55.85, end: 63.05),
                ChantLine(latin: "O Jesu pie!", english: "O loving Jesus,", start: 63.05, end: 70.17),
                ChantLine(latin: "O Jesu fili Maríæ.", english: "O Jesus, Son of Mary.", start: 70.17, end: 81.88)
            ]
        ),
        Chant(
            id: "o_salutaris",
            groupID: "sacrament",
            latinTitle: "O Salutaris Hostia",
            englishTitle: "O Saving Victim",
            setting: nil,
            detail: "Sung as the Host is placed on the altar for adoration",
            prayerIDs: ["o_salutaris"],
            duration: 66.0,
            score: [
                ChantScorePart(file: "chant-o-salutaris-hostia-i", caption: "O salutaris Hostia", aspectRatio: 2.3522)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/o-salutaris-hostia-i/")!,
            lines: [
                ChantLine(latin: "O salutáris Hóstia,", english: "O saving Victim,", start: 0.53, end: 8.15),
                ChantLine(latin: "Quæ cæli pandis óstium, Bella premunt hostília,", english: "Who openest the gate of heaven, hostile wars press hard upon us:", start: 8.15, end: 19.03),
                ChantLine(latin: "Da robur, fer auxílium.", english: "give strength, bring aid.", start: 19.03, end: 26.18),
                ChantLine(latin: "Uni trinóque Dómino", english: "To the Lord, One and Three,", start: 27.01, end: 34.63),
                ChantLine(latin: "Sit sempitérna glória, Qui vitam sine término", english: "be glory everlasting; Who life without an end", start: 34.63, end: 45.45),
                ChantLine(latin: "Nobis donet in pátria.", english: "may grant us in our homeland.", start: 45.45, end: 52.90),
                ChantLine(latin: "Amen.", english: "Amen.", start: 53.13, end: 62.36)
            ]
        ),
        Chant(
            id: "tantum_ergo",
            groupID: "sacrament",
            latinTitle: "Tantum Ergo",
            englishTitle: "Down in Adoration Falling",
            setting: nil,
            detail: "Sung before the blessing at Benediction",
            prayerIDs: ["tantum_ergo"],
            duration: 137.4,
            score: [
                ChantScorePart(file: "chant-tantum-ergo-i", caption: "Tantum ergo", aspectRatio: 1.3729),
                ChantScorePart(file: "chant-vers-panem-de-caelo", caption: "Panem de caelo", aspectRatio: 3.9357),
                ChantScorePart(file: "chant-or-deus-qui-nobis", caption: "Oremus. Deus qui nobis", aspectRatio: 1.8202)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/tantum-ergo-i/")!,
            lines: [
                ChantLine(latin: "Tantum ergo Sacraméntum", english: "So great a Sacrament, therefore,", start: 0.29, end: 6.37),
                ChantLine(latin: "Venerémur cérnui:", english: "let us venerate, bowing low;", start: 6.41, end: 12.33),
                ChantLine(latin: "Et antíquum documéntum", english: "and let the former teaching", start: 12.33, end: 17.55),
                ChantLine(latin: "Novo cedat rítui:", english: "give way to the new rite;", start: 17.55, end: 23.41),
                ChantLine(latin: "Præstet fides suppleméntum", english: "let faith provide its aid", start: 23.41, end: 28.77),
                ChantLine(latin: "Sénsuum deféctui.", english: "for the failing of the senses.", start: 28.77, end: 34.16),
                ChantLine(latin: "Genitóri, Genitóque", english: "To the Begetter and the Begotten", start: 35.73, end: 41.63),
                ChantLine(latin: "Laus et jubilátio,", english: "be praise and jubilation,", start: 41.70, end: 47.69),
                ChantLine(latin: "Salus, honor, virtus quoque", english: "salvation, honour, and might also,", start: 47.69, end: 52.81),
                ChantLine(latin: "Sit et benedíctio:", english: "and blessing be to Them;", start: 52.81, end: 58.45),
                ChantLine(latin: "Procedénti ab utróque", english: "to Him Who proceedeth from Both", start: 58.45, end: 63.75),
                ChantLine(latin: "Compar sit laudátio.", english: "be equal praise.", start: 63.75, end: 69.76),
                ChantLine(latin: "Amen.", english: "Amen.", start: 70.85, end: 78.80),
                ChantLine(latin: "Panem de cælo præstitísti eis.", english: "Thou didst give them bread from heaven.", start: 81.09, end: 86.41),
                ChantLine(latin: "Omne delectaméntum in se habéntem.", english: "Containing in itself all delight.", start: 86.41, end: 92.35),
                ChantLine(latin: "Orémus.", english: "Let us pray.", start: 92.35, end: 95.81),
                ChantLine(latin: "Deus, qui nobis sub Sacraménto mirábili passiónis tuæ memóriam reliquísti:", english: "O God, Who under a wonderful Sacrament hast left us a memorial of Thy Passion,", start: 95.81, end: 104.37),
                ChantLine(latin: "tríbue, quǽsumus,", english: "grant us, we beseech Thee,", start: 104.37, end: 107.11),
                ChantLine(latin: "ita nos córporis et sánguinis tui sacra mystéria venerári;", english: "so to venerate the sacred mysteries of Thy Body and Blood,", start: 107.13, end: 113.89),
                ChantLine(latin: "ut redemptiónis tuæ fructum in nobis júgiter sentiámus.", english: "that we may continually feel within ourselves the fruit of Thy redemption.", start: 113.89, end: 121.41),
                ChantLine(latin: "Qui vivis et regnas in sǽcula sæculórum.", english: "Who livest and reignest world without end.", start: 121.41, end: 128.69),
                ChantLine(latin: "Amen.", english: "Amen.", start: 128.69, end: 133.90)
            ]
        ),
        Chant(
            id: "o_sacrum_convivium",
            groupID: "sacrament",
            latinTitle: "O Sacrum Convivium",
            englishTitle: "O Sacred Banquet",
            setting: nil,
            detail: "Sung at evening prayer on Corpus Christi, the feast of the Body of Christ",
            prayerIDs: ["o_sacrum_convivium"],
            duration: 118.0,
            score: [
                ChantScorePart(file: "chant-o-sacrum-convivium", caption: "O sacrum convivium", aspectRatio: 1.6858)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/o-sacrum-convivium/")!,
            lines: [
                ChantLine(latin: "O sacrum convívium!", english: "O sacred banquet,", start: 0.27, end: 11.37),
                ChantLine(latin: "in quo Christus súmitur:", english: "in which Christ is received,", start: 11.37, end: 21.27),
                ChantLine(latin: "recólitur memória", english: "the memory is renewed", start: 21.27, end: 29.85),
                ChantLine(latin: "passiónis ejus:", english: "of His Passion,", start: 29.85, end: 37.57),
                ChantLine(latin: "mens implétur grátia:", english: "the mind is filled with grace,", start: 37.57, end: 46.44),
                ChantLine(latin: "et futúræ glóriæ", english: "and of future glory", start: 46.47, end: 55.74),
                ChantLine(latin: "nobis pignus datur,", english: "a pledge is given to us.", start: 56.01, end: 64.93),
                ChantLine(latin: "allelúia.", english: "Alleluia.", start: 64.93, end: 85.60),
                ChantLine(latin: "nobis pignus datur.", english: "A pledge is given to us.", start: 90.21, end: 113.60)
            ]
        ),
        Chant(
            id: "divine_praises",
            groupID: "sacrament",
            latinTitle: "Laudes Divinæ",
            englishTitle: "The Divine Praises",
            setting: nil,
            detail: "Said or sung after the blessing at Benediction",
            prayerIDs: ["divine_praises"],
            duration: 127.1,
            score: [
                ChantScorePart(file: "chant-laudes-divinae", caption: "Laudes Divinae", aspectRatio: 0.7377)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/laudes-divinae/")!,
            lines: [
                ChantLine(latin: "Benedíctus Deus, Benedíctum nomen sanctum ejus.", english: "Blessed be God. Blessed be His holy Name.", start: 0.15, end: 8.79),
                ChantLine(latin: "Benedíctus Jesus Christus verus Deus et verus homo.", english: "Blessed be Jesus Christ, true God and true Man.", start: 8.79, end: 17.83),
                ChantLine(latin: "Benedíctum nomen Jesu. Benedíctum Cor ejus sacratíssimum.", english: "Blessed be the Name of Jesus. Blessed be His most Sacred Heart.", start: 17.83, end: 28.13),
                ChantLine(latin: "Benedíctus ejus Sanguis pretiosíssimus.", english: "Blessed be His most Precious Blood.", start: 28.13, end: 36.59),
                ChantLine(latin: "Benedíctus Jesus in sanctíssimo altáris Sacraménto.", english: "Blessed be Jesus in the most holy Sacrament of the altar.", start: 36.59, end: 46.13),
                ChantLine(latin: "Benedíctus Sanctus Spíritus Paráclitus.", english: "Blessed be the Holy Ghost, the Paraclete.", start: 46.13, end: 54.69),
                ChantLine(latin: "Benedícta magna Mater Dei, María sanctíssima.", english: "Blessed be the great Mother of God, Mary most holy.", start: 54.69, end: 63.95),
                ChantLine(latin: "Benedícta sancta ejus et immaculáta Concéptio.", english: "Blessed be her holy and Immaculate Conception.", start: 63.95, end: 73.81),
                ChantLine(latin: "Benedícta ejus gloriósa Assúmptio.", english: "Blessed be her glorious Assumption.", start: 73.81, end: 82.79),
                ChantLine(latin: "Benedíctum nomen Maríæ,", english: "Blessed be the name of Mary,", start: 82.79, end: 87.65),
                ChantLine(latin: "Vírginis et Matris.", english: "Virgin and Mother.", start: 87.68, end: 92.51),
                ChantLine(latin: "Benedíctus sanctus Joseph,", english: "Blessed be St Joseph,", start: 92.51, end: 97.11),
                ChantLine(latin: "ejus castíssimus Sponsus.", english: "her most chaste spouse.", start: 97.11, end: 102.39),
                ChantLine(latin: "Benedíctus Deus in Ángelis suis,", english: "Blessed be God in His Angels", start: 102.39, end: 108.57),
                ChantLine(latin: "et in Sanctis suis.", english: "and in His Saints.", start: 108.57, end: 114.66),
                ChantLine(latin: "Fiat! Fiat!", english: "So be it! So be it!", start: 114.83, end: 122.58)
            ]
        ),
        Chant(
            id: "anima_christi",
            groupID: "sacrament",
            latinTitle: "Anima Christi",
            englishTitle: "Soul of Christ",
            setting: nil,
            detail: "A thanksgiving after Communion",
            prayerIDs: ["anima_christi"],
            duration: 90.0,
            score: [
                ChantScorePart(file: "chant-anima-christi-i", caption: "Anima Christi", aspectRatio: 1.1418)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/anima-christi-i/")!,
            lines: [
                ChantLine(latin: "Ánima Christi, sanctífica me:", english: "Soul of Christ, sanctify me.", start: 0.25, end: 6.41),
                ChantLine(latin: "Corpus Christi, salva me.", english: "Body of Christ, save me.", start: 6.41, end: 12.84),
                ChantLine(latin: "Sanguis Christi, inébria me:", english: "Blood of Christ, inebriate me.", start: 13.01, end: 19.03),
                ChantLine(latin: "aqua láteris Christi, lava me.", english: "Water from the side of Christ, wash me.", start: 19.03, end: 26.38),
                ChantLine(latin: "Pássio Christi, confórta me:", english: "Passion of Christ, strengthen me.", start: 26.55, end: 32.03),
                ChantLine(latin: "O bone Jesu, exáudi me.", english: "O good Jesus, hear me.", start: 32.03, end: 39.62),
                ChantLine(latin: "Intra tua vúlnera abscónde me:", english: "Within Thy wounds hide me.", start: 39.69, end: 45.59),
                ChantLine(latin: "ne permíttas me separári a te.", english: "Suffer me not to be separated from Thee.", start: 45.59, end: 53.06),
                ChantLine(latin: "Ab hoste malígno defénde me:", english: "From the malicious enemy defend me.", start: 53.23, end: 58.81),
                ChantLine(latin: "in hora mortis meæ voca me.", english: "In the hour of my death call me,", start: 58.81, end: 66.06),
                ChantLine(latin: "Et jube me veníre ad te:", english: "and bid me come to Thee,", start: 66.09, end: 71.87),
                ChantLine(latin: "ut cum Sanctis tuis laudem te", english: "that with Thy Saints I may praise Thee", start: 71.87, end: 77.11),
                ChantLine(latin: "in sǽcula sæculórum. Amen.", english: "for ever and ever. Amen.", start: 77.11, end: 85.30)
            ]
        ),
        Chant(
            id: "panis_angelicus",
            groupID: "sacrament",
            latinTitle: "Panis Angelicus",
            englishTitle: "Bread of Angels",
            setting: nil,
            detail: "From St Thomas's hymn for the night prayer of Corpus Christi",
            prayerIDs: [],
            duration: 87.0,
            score: [
                ChantScorePart(file: "chant-panis-angelicus", caption: "Panis angelicus", aspectRatio: 1.3132)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/panis-angelicus-1/")!,
            lines: [
                ChantLine(latin: "Panis angélicus", english: "The bread of Angels", start: 0.39, end: 7.87),
                ChantLine(latin: "fit panis hóminum;", english: "becomes the bread of men;", start: 7.87, end: 11.26),
                ChantLine(latin: "Dat panis cǽlicus", english: "the bread of heaven", start: 11.49, end: 16.09),
                ChantLine(latin: "figúris términum:", english: "puts an end to figures.", start: 16.09, end: 19.62),
                ChantLine(latin: "O res mirábilis!", english: "O wondrous thing!", start: 20.77, end: 24.37),
                ChantLine(latin: "mandúcat Dóminum", english: "there feeds upon the Lord", start: 24.37, end: 29.26),
                ChantLine(latin: "Pauper, servus, et húmilis.", english: "the poor man, the servant, and the lowly.", start: 29.37, end: 36.24),
                ChantLine(latin: "Te trina Déitas", english: "Thee, Godhead three", start: 38.29, end: 45.23),
                ChantLine(latin: "únaque póscimus:", english: "and one, we beseech:", start: 45.23, end: 49.09),
                ChantLine(latin: "Sic nos tu vísita,", english: "so do Thou visit us", start: 49.09, end: 53.85),
                ChantLine(latin: "sicut te cólimus;", english: "as we worship Thee;", start: 53.85, end: 57.56),
                ChantLine(latin: "Per tuas sémitas", english: "by Thy paths", start: 58.67, end: 62.39),
                ChantLine(latin: "duc nos quo téndimus,", english: "lead us whither we are bound,", start: 62.39, end: 67.33),
                ChantLine(latin: "Ad lucem quam inhábitas.", english: "to the light wherein Thou dwellest.", start: 67.33, end: 74.58),
                ChantLine(latin: "Amen.", english: "Amen.", start: 75.95, end: 81.14)
            ]
        ),
        Chant(
            id: "lauda_sion",
            groupID: "sacrament",
            latinTitle: "Lauda Sion",
            englishTitle: "Praise, O Sion",
            setting: nil,
            detail: "The feast poem of Corpus Christi, the feast of the Body of Christ",
            prayerIDs: [],
            duration: 438.0,
            score: [
                ChantScorePart(file: "chant-lauda-sion-salvatorem", caption: "Lauda Sion Salvatorem", aspectRatio: 0.2300)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/lauda-sion-salvatorem/")!,
            lines: [
                ChantLine(latin: "Lauda Sion Salvatórem,", english: "Praise, O Sion, thy Saviour,", start: 0.45, end: 5.23),
                ChantLine(latin: "Lauda ducem et pastórem,", english: "praise thy leader and thy shepherd", start: 5.23, end: 10.59),
                ChantLine(latin: "In hymnis et cánticis.", english: "in hymns and canticles.", start: 10.59, end: 15.12),
                ChantLine(latin: "Quantum potes, tantum aude:", english: "As much as thou canst, so much dare,", start: 16.09, end: 20.89),
                ChantLine(latin: "Quia major omni laude,", english: "for He is greater than all praise,", start: 20.89, end: 26.07),
                ChantLine(latin: "Nec laudáre súfficis.", english: "nor art thou able to praise Him enough.", start: 26.07, end: 30.22),
                ChantLine(latin: "Laudis thema speciális,", english: "A theme of special praise,", start: 31.75, end: 37.83),
                ChantLine(latin: "Panis vivus et vitális", english: "the living and life-giving Bread,", start: 37.83, end: 42.44),
                ChantLine(latin: "Hódie propónitur.", english: "is set before us this day.", start: 42.65, end: 47.24),
                ChantLine(latin: "Quem in sacræ mensa cœnæ,", english: "That at the table of the holy Supper", start: 48.03, end: 54.33),
                ChantLine(latin: "Turbæ fratrum duodénæ", english: "to the band of the twelve brethren", start: 54.33, end: 59.25),
                ChantLine(latin: "Datum non ambígitur.", english: "it was given, none doubteth.", start: 59.25, end: 64.22),
                ChantLine(latin: "Sit laus plena, sit sonóra, Sit jucúnda, sit decóra", english: "Let praise be full, let it be resounding, let it be joyful, let it be comely,", start: 65.07, end: 75.07),
                ChantLine(latin: "Mentis jubilátio.", english: "the jubilation of the mind.", start: 75.07, end: 79.36),
                ChantLine(latin: "Dies enim solémnis ágitur,", english: "For the solemn day is kept", start: 80.53, end: 86.92),
                ChantLine(latin: "In qua mensæ prima recólitur", english: "on which is recalled the first", start: 87.15, end: 93.38),
                ChantLine(latin: "Hujus institútio.", english: "institution of this table.", start: 93.45, end: 98.32),
                ChantLine(latin: "In hac mensa novi Regis,", english: "At this table of the new King,", start: 99.03, end: 104.01),
                ChantLine(latin: "Novum Pascha novæ legis,", english: "the new Pasch of the new law", start: 104.01, end: 108.99),
                ChantLine(latin: "Phase vetus términat.", english: "endeth the old Passover.", start: 108.99, end: 113.28),
                ChantLine(latin: "Vetustátem nóvitas,", english: "The new puts the old to flight,", start: 114.47, end: 119.99),
                ChantLine(latin: "Umbram fugat véritas,", english: "the truth puts the shadow to flight,", start: 119.99, end: 125.51),
                ChantLine(latin: "Noctem lux elíminat.", english: "the light drives out the night.", start: 125.51, end: 129.92),
                ChantLine(latin: "Quod in cœna Christus gessit,", english: "What Christ did at the Supper,", start: 131.07, end: 136.05),
                ChantLine(latin: "Faciéndum hoc expréssit", english: "this He bade be done", start: 136.05, end: 140.81),
                ChantLine(latin: "In sui memóriam.", english: "in memory of Him.", start: 140.81, end: 145.58),
                ChantLine(latin: "Docti sacris institútis,", english: "Taught by His holy ordinances,", start: 146.35, end: 151.47),
                ChantLine(latin: "Panem, vinum in salútis", english: "bread and wine into the saving", start: 151.47, end: 156.31),
                ChantLine(latin: "Consecrámus hóstiam.", english: "Victim we consecrate.", start: 156.31, end: 161.22),
                ChantLine(latin: "Dogma datur christiánis,", english: "This doctrine is given to Christians,", start: 161.67, end: 166.23),
                ChantLine(latin: "Quod in carnem transit panis,", english: "that bread passeth into flesh,", start: 166.23, end: 170.97),
                ChantLine(latin: "Et vinum in sánguinem.", english: "and wine into blood.", start: 170.97, end: 175.96),
                ChantLine(latin: "Quod non capis, quod non vides,", english: "What thou dost not understand, what thou dost not see,", start: 176.81, end: 181.39),
                ChantLine(latin: "Animósa firmat fides,", english: "a lively faith confirmeth,", start: 181.39, end: 186.15),
                ChantLine(latin: "Præter rerum órdinem.", english: "beyond the order of nature.", start: 186.15, end: 191.22),
                ChantLine(latin: "Sub divérsis speciébus,", english: "Under differing species,", start: 192.37, end: 198.25),
                ChantLine(latin: "Signis tantum, et non rebus,", english: "signs only and not things,", start: 198.25, end: 202.95),
                ChantLine(latin: "Latent res exímiæ.", english: "lie hidden wondrous realities.", start: 202.95, end: 207.54),
                ChantLine(latin: "Caro cibus, sanguis potus:", english: "Flesh is meat, blood is drink;", start: 208.61, end: 214.65),
                ChantLine(latin: "Manet tamen Christus totus", english: "yet Christ remaineth whole", start: 214.65, end: 219.67),
                ChantLine(latin: "Sub utráque spécie.", english: "under either species.", start: 219.67, end: 224.34),
                ChantLine(latin: "A suménte non concísus,", english: "By him who receiveth He is not cut,", start: 225.23, end: 230.33),
                ChantLine(latin: "Non confráctus, non divísus:", english: "not broken, not divided;", start: 230.33, end: 235.09),
                ChantLine(latin: "Ínteger accípitur.", english: "whole is He received.", start: 235.09, end: 240.14),
                ChantLine(latin: "Sumit unus, sumunt mille:", english: "One receiveth, a thousand receive;", start: 241.29, end: 246.17),
                ChantLine(latin: "Quantum isti, tantum ille: Nec sumptus consúmitur.", english: "as much as these, so much the one; nor, received, is He consumed.", start: 246.17, end: 255.86),
                ChantLine(latin: "Sumunt boni, sumunt mali:", english: "The good receive, the wicked receive,", start: 256.79, end: 262.03),
                ChantLine(latin: "Sorte tamen inæquáli,", english: "yet with unequal lot,", start: 262.03, end: 266.79),
                ChantLine(latin: "Vitæ vel intéritus.", english: "of life or of destruction.", start: 266.79, end: 271.22),
                ChantLine(latin: "Mors est malis, vita bonis:", english: "Death to the wicked, life to the good:", start: 272.53, end: 278.11),
                ChantLine(latin: "Vide paris sumptiónis", english: "see, of a like receiving,", start: 278.11, end: 282.87),
                ChantLine(latin: "Quam sit dispar éxitus.", english: "how unlike is the issue.", start: 282.87, end: 287.52),
                ChantLine(latin: "Fracto demum sacraménto,", english: "When at last the Sacrament is broken,", start: 288.49, end: 293.31),
                ChantLine(latin: "Ne vacíles, sed meménto", english: "waver not, but remember", start: 293.31, end: 297.81),
                ChantLine(latin: "Tantum esse sub fragménto,", english: "that there is as much in a fragment", start: 297.81, end: 302.53),
                ChantLine(latin: "Quantum toto tégitur.", english: "as is hidden in the whole.", start: 302.53, end: 307.46),
                ChantLine(latin: "Nulla rei fit scissúra:", english: "No division is made of the substance;", start: 308.51, end: 313.27),
                ChantLine(latin: "Signi tantum fit fractúra,", english: "the breaking is of the sign alone,", start: 313.27, end: 317.81),
                ChantLine(latin: "Qua nec status, nec statúra", english: "by which neither the state nor the stature", start: 317.81, end: 322.49),
                ChantLine(latin: "Signáti minúitur.", english: "of the One signified is lessened.", start: 322.49, end: 327.20),
                ChantLine(latin: "Ecce panis Angelórum,", english: "Behold the Bread of Angels,", start: 328.65, end: 333.75),
                ChantLine(latin: "Factus cibus viatórum:", english: "made the food of wayfarers,", start: 333.75, end: 338.23),
                ChantLine(latin: "Vere panis filiórum,", english: "truly the bread of children,", start: 338.23, end: 343.25),
                ChantLine(latin: "Non mitténdus cánibus.", english: "not to be cast to the dogs.", start: 343.25, end: 348.18),
                ChantLine(latin: "In figúris præsignátur,", english: "In figures it is foreshown,", start: 349.37, end: 354.31),
                ChantLine(latin: "Cum Ísaac immolátur,", english: "when Isaac is offered,", start: 354.31, end: 358.93),
                ChantLine(latin: "Agnus Paschæ deputátur,", english: "the Paschal Lamb appointed,", start: 358.93, end: 364.17),
                ChantLine(latin: "Datur manna pátribus.", english: "manna given to the fathers.", start: 364.17, end: 369.26),
                ChantLine(latin: "Bone pastor, panis vere,", english: "Good Shepherd, true Bread,", start: 370.29, end: 375.45),
                ChantLine(latin: "Jesu, nostri miserére:", english: "Jesus, have mercy on us;", start: 375.45, end: 381.31),
                ChantLine(latin: "Tu nos pasce, nos tuére,", english: "do Thou feed us, defend us,", start: 381.31, end: 385.97),
                ChantLine(latin: "Tu nos bona fac vidére", english: "do Thou make us see good things", start: 385.97, end: 391.23),
                ChantLine(latin: "In terra vivéntium.", english: "in the land of the living.", start: 391.23, end: 396.06),
                ChantLine(latin: "Tu qui cuncta scis et vales,", english: "Thou who knowest and canst all things,", start: 396.95, end: 402.31),
                ChantLine(latin: "Qui nos pascis hic mortáles:", english: "who feedest us here as mortals,", start: 402.31, end: 408.15),
                ChantLine(latin: "Tuos ibi commensáles,", english: "Thy fellow guests there,", start: 408.15, end: 412.89),
                ChantLine(latin: "Coherédes et sodáles", english: "fellow heirs and companions", start: 412.89, end: 417.74),
                ChantLine(latin: "Fac sanctórum cívium.", english: "make us of the holy citizens.", start: 417.79, end: 422.78),
                ChantLine(latin: "Amen.", english: "Amen.", start: 424.45, end: 427.59),
                ChantLine(latin: "Allelúia.", english: "Alleluia.", start: 427.59, end: 432.30)
            ]
        ),
