                ChantLine(latin: "Dulce refrigérium.", english: "sweet refreshment.", start: 38.09, end: 43.16),
                ChantLine(latin: "In labóre réquies, In æstu tempéries,", english: "In labour, rest; in heat, coolness;", start: 44.25, end: 53.25),
                ChantLine(latin: "In fletu solátium.", english: "in weeping, solace.", start: 53.25, end: 58.90),
                ChantLine(latin: "O lux beatíssima, Reple cordis íntima", english: "O most blessed Light, fill the inmost heart", start: 59.59, end: 67.99),
                ChantLine(latin: "Tuórum fidélium.", english: "of Thy faithful.", start: 68.03, end: 73.16),
                ChantLine(latin: "Sine tuo númine,", english: "Without Thy divine power", start: 74.29, end: 78.85),
                ChantLine(latin: "Nihil est in hómine,", english: "there is nothing in man,", start: 78.85, end: 82.67),
                ChantLine(latin: "Nihil est innóxium.", english: "nothing that is without harm.", start: 82.67, end: 87.86),
                ChantLine(latin: "Lava quod est sórdidum,", english: "Wash what is soiled,", start: 89.07, end: 93.75),
                ChantLine(latin: "Riga quod est áridum,", english: "water what is dry,", start: 93.76, end: 98.69),
                ChantLine(latin: "Sana quod est sáucium.", english: "heal what is wounded.", start: 98.69, end: 103.39),
                ChantLine(latin: "Flecte quod est rígidum, Fove quod est frígidum,", english: "Bend what is stiff, warm what is cold,", start: 103.39, end: 112.76),
                ChantLine(latin: "Rege quod est dévium.", english: "guide what has strayed.", start: 112.83, end: 117.71),
                ChantLine(latin: "Da tuis fidélibus, In te confidéntibus,", english: "Give to Thy faithful, who trust in Thee,", start: 117.71, end: 126.07),
                ChantLine(latin: "Sacrum septenárium.", english: "the sacred sevenfold gift.", start: 126.07, end: 130.42),
                ChantLine(latin: "Da virtútis méritum, Da salútis éxitum,", english: "Give the reward of virtue, give a saving end,", start: 130.89, end: 139.31),
                ChantLine(latin: "Da perénne gáudium.", english: "give everlasting joy.", start: 139.31, end: 143.56),
                ChantLine(latin: "Amen. Allelúia.", english: "Amen. Alleluia.", start: 144.89, end: 152.66)
            ]
