                ChantLine(latin: "Orémus.", english: "Let us pray.", start: 805.09, end: 808.37),
                ChantLine(latin: "Dómine Jesu Christe, qui dixísti:", english: "O Lord Jesus Christ, Who hast said:", start: 808.37, end: 812.43),
                ChantLine(latin: "pétite, et accipiétis; quǽrite, et inveniétis; pulsáte, et aperiétur vobis;", english: "Ask and ye shall receive, seek and ye shall find, knock and it shall be opened unto you;", start: 812.43, end: 821.71),
                ChantLine(latin: "quǽsumus, da nobis peténtibus diviníssimi tui amóris afféctum,", english: "grant, we beseech Thee, to us who ask the gift of Thy divine love,", start: 821.71, end: 829.59),
                ChantLine(latin: "ut te toto corde, ore et ópere diligámus, et a tua nunquam laude cessémus.", english: "that we may ever love Thee with all our hearts, and in all our words and actions, and never cease from praising Thee.", start: 829.59, end: 838.42),
                ChantLine(latin: "Sancti nóminis tui, Dómine, timórem páriter et amórem fac nos habére perpétuum,", english: "Give us, O Lord, a perpetual fear and love of Thy holy Name;", start: 839.19, end: 847.67),
                ChantLine(latin: "quia nunquam tua gubernatióne destítuis,", english: "for Thou never failest to govern", start: 847.67, end: 853.07),
                ChantLine(latin: "quos in soliditáte tuæ dilectiónis instítuis.", english: "those whom Thou dost solidly establish in Thy love,", start: 853.07, end: 859.48),
                ChantLine(latin: "Qui vivis et regnas in sǽcula sæculórum.", english: "Who livest and reignest world without end.", start: 859.51, end: 866.22),
                ChantLine(latin: "Amen.", english: "Amen.", start: 866.51, end: 870.62)
            ]
        ),
        Chant(
            id: "jesu_dulcis_memoria",
            groupID: "ourLord",
            latinTitle: "Jesu Dulcis Memoria",
            englishTitle: "Jesus, the Very Thought of Thee",
            setting: nil,
            detail: "The hymn of the Holy Name",
            prayerIDs: [],
            duration: 116.1,
            score: [
                ChantScorePart(file: "chant-jesu-dulcis-memoria", caption: "Jesu dulcis memoria", aspectRatio: 0.8348)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/jesu-dulcis-memoria/")!,
            lines: [
                ChantLine(latin: "Jesu, dulcis memória,", english: "Jesus, sweet remembrance,", start: 0.35, end: 4.87),
                ChantLine(latin: "Dans vera cordis gáudia:", english: "giving true joys to the heart:", start: 4.87, end: 9.71),
                ChantLine(latin: "Sed super mel et ómnia Ejus dulcis præséntia.", english: "but above honey and all things is His sweet presence.", start: 9.71, end: 20.52),
                ChantLine(latin: "Nil cánitur suávius,", english: "Nothing more delightful is sung,", start: 20.79, end: 25.33),
                ChantLine(latin: "Nil audítur jucúndius,", english: "nothing more pleasing is heard,", start: 25.33, end: 30.15),
                ChantLine(latin: "Nil cogitátur dúlcius,", english: "nothing sweeter is thought upon,", start: 30.15, end: 35.53),
                ChantLine(latin: "Quam Jesus Dei Fílius.", english: "than Jesus, the Son of God.", start: 35.53, end: 40.74),
                ChantLine(latin: "Jesu, spes pœniténtibus,", english: "Jesus, hope of the penitent,", start: 41.67, end: 46.49),
                ChantLine(latin: "Quam pius es peténtibus!", english: "how loving Thou art to those who ask!", start: 46.49, end: 51.47),
                ChantLine(latin: "Quam bonus te quæréntibus!", english: "How good to those who seek Thee!", start: 51.47, end: 57.05),
                ChantLine(latin: "Sed quid inveniéntibus!", english: "But what to those who find!", start: 57.05, end: 61.86),
                ChantLine(latin: "Nec lingua valet dícere,", english: "No tongue can tell it,", start: 63.01, end: 67.73),
                ChantLine(latin: "Nec líttera exprímere:", english: "nor any letter express it:", start: 67.73, end: 72.79),
                ChantLine(latin: "Expértus potest crédere,", english: "one who has known it can believe", start: 72.79, end: 77.71),
                ChantLine(latin: "Quid sit Jesum dilígere.", english: "what it is to love Jesus.", start: 77.71, end: 83.62),
                ChantLine(latin: "Sis, Jesu, nostrum gáudium,", english: "Be Thou, Jesus, our joy,", start: 84.39, end: 89.01),
                ChantLine(latin: "Qui es futúrus prǽmium:", english: "who art to be our reward:", start: 89.01, end: 94.01),
                ChantLine(latin: "Sit nostra in te glória,", english: "may our glory be in Thee", start: 94.01, end: 99.35),
                ChantLine(latin: "Per cuncta semper sǽcula.", english: "through all ages for ever.", start: 99.35, end: 105.44),
                ChantLine(latin: "Amen.", english: "Amen.", start: 105.57, end: 111.34)
            ]
        ),
