                ChantLine(latin: "Laudáte Dóminum, omnes Gentes: laudáte eum, omnes pópuli:", english: "Praise the Lord, all ye nations: praise Him, all ye peoples.", start: 22.65, end: 33.58),
                ChantLine(latin: "Christus vincit, Christus regnat,", english: "Christ conquers, Christ reigns,", start: 34.71, end: 40.27),
                ChantLine(latin: "Christus ímperat.", english: "Christ commands.", start: 40.27, end: 45.32),
                ChantLine(latin: "Quóniam confirmáta est super nos misericórdia ejus:", english: "For His mercy is confirmed upon us:", start: 46.07, end: 54.10),
                ChantLine(latin: "et véritas Dómini manet in ætérnum.", english: "and the truth of the Lord remaineth for ever.", start: 54.61, end: 61.38),
                ChantLine(latin: "Christus vincit, Christus regnat, Christus ímperat.", english: "Christ conquers, Christ reigns, Christ commands.", start: 62.65, end: 73.08),
                ChantLine(latin: "Glória Patri, et Fílio,", english: "Glory be to the Father, and to the Son,", start: 74.11, end: 80.45),
                ChantLine(latin: "et Spirítui Sancto.", english: "and to the Holy Ghost.", start: 80.45, end: 85.84),
                ChantLine(latin: "Christus vincit, Christus regnat, Christus ímperat.", english: "Christ conquers, Christ reigns, Christ commands.", start: 86.95, end: 97.40),
                ChantLine(latin: "Sicut erat in princípio, et nunc, et semper,", english: "As it was in the beginning, is now, and ever shall be,", start: 98.55, end: 105.65),
                ChantLine(latin: "et in sǽcula sæculórum. Amen.", english: "world without end. Amen.", start: 105.65, end: 112.66),
                ChantLine(latin: "Christus vincit, Christus regnat, Christus ímperat.", english: "Christ conquers, Christ reigns, Christ commands.", start: 113.39, end: 123.86)
            ]
        ),
