            lines: [
                ChantLine(latin: "Sancte Míchaël archángele, defénde nos in prǽlio;", english: "Saint Michael the Archangel, defend us in battle.", start: 0.45, end: 13.21),
                ChantLine(latin: "contra nequítiam et insídias diáboli", english: "Against the wickedness and snares of the devil", start: 13.21, end: 22.75),
                ChantLine(latin: "esto præsídium.", english: "be our safeguard.", start: 22.75, end: 29.58),
                ChantLine(latin: "Ímperet illi Deus,", english: "May God rebuke him,", start: 30.17, end: 37.03),
                ChantLine(latin: "súpplices deprecámur:", english: "we humbly pray;", start: 37.03, end: 42.83),
                ChantLine(latin: "tuque princeps milítiæ cœléstis,", english: "and do thou, O Prince of the heavenly hosts,", start: 42.83, end: 50.81),
                ChantLine(latin: "Sátanam aliósque spíritus malígnos,", english: "Satan and all the evil spirits,", start: 50.81, end: 59.03),
                ChantLine(latin: "qui ad perditiónem animárum", english: "who, seeking the ruin of souls,", start: 59.03, end: 68.53),
                ChantLine(latin: "pervagántur in mundo,", english: "prowl about the world,", start: 68.53, end: 74.95),
                ChantLine(latin: "divína virtúte", english: "by the power of God,", start: 74.95, end: 79.25),
