            lines: [
                ChantLine(latin: "Te Joseph célebrent ágmina cǽlitum:", english: "Let the hosts of heaven celebrate thee, Joseph;", start: 0.21, end: 9.35),
                ChantLine(latin: "Te cuncti résonent christíadum chori,", english: "let all the choirs of Christians resound with thy praise,", start: 9.35, end: 18.05),
                ChantLine(latin: "Qui clarus méritis, junctus es ínclytæ", english: "who, glorious in merit, wast joined", start: 18.05, end: 27.37),
                ChantLine(latin: "Casto fœdere Vírgini.", english: "in chaste wedlock to the renowned Virgin.", start: 27.37, end: 35.40),
                ChantLine(latin: "Almo cum túmidam gérmine cónjugem", english: "When thy spouse was great with the holy Child,", start: 36.15, end: 45.26),
                ChantLine(latin: "Admírans, dúbio tángeris ánxius,", english: "marvelling, thou art troubled with anxious doubt;", start: 45.69, end: 54.43),
                ChantLine(latin: "Afflátu súperi Fláminis Ángelus", english: "by the breath of the Spirit from on high, an Angel", start: 54.43, end: 63.76),
                ChantLine(latin: "Concéptum púerum docet.", english: "teacheth that the Child was conceived.", start: 64.21, end: 71.56),
                ChantLine(latin: "Tu natum Dóminum stringis, ad éxteras", english: "Thou embracest the new-born Lord; to the far lands", start: 72.49, end: 81.30),
                ChantLine(latin: "Ægýpti prófugum tu séqueris plagas:", english: "of Egypt thou followest Him, a fugitive;", start: 81.75, end: 90.79),
                ChantLine(latin: "Amíssum Sólymis quǽris, et ínvenis,", english: "lost in Jerusalem, thou seekest Him, and findest Him,", start: 90.79, end: 100.12),
                ChantLine(latin: "Miscens gáudia flétibus.", english: "mingling joys with tears.", start: 100.79, end: 108.12),
                ChantLine(latin: "Post mortem réliquos sors pia cónsecrat,", english: "Others a holy lot doth consecrate after death,", start: 109.41, end: 118.71),
                ChantLine(latin: "Palmámque eméritos glória súscipit:", english: "and glory receives them when they have won the palm;", start: 118.71, end: 127.85),
                ChantLine(latin: "Tu vivens, Súperis par, frúeris Deo,", english: "thou, while living, like to the Saints above, enjoyest God,", start: 127.85, end: 137.41),
                ChantLine(latin: "Mira sorte beátior.", english: "more blessed by a wondrous lot.", start: 137.41, end: 145.58),
                ChantLine(latin: "Nobis, summa Trias, parce precántibus:", english: "Spare us who pray to Thee, O Trinity most high;", start: 146.39, end: 155.67),
                ChantLine(latin: "Da Joseph méritis sídera scándere,", english: "grant us by the merits of Joseph to climb to the stars,", start: 155.67, end: 164.87),
                ChantLine(latin: "Ut tandem líceat nos tibi pérpetim", english: "that at length it may be given us for ever", start: 164.87, end: 174.60),
                ChantLine(latin: "Gratum prómere cánticum.", english: "to pour forth to Thee a pleasing song.", start: 174.63, end: 183.24),
                ChantLine(latin: "Amen.", english: "Amen.", start: 183.87, end: 192.86)
            ]
