                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 621.59, end: 626.03),
                ChantLine(latin: "Ab ira, et ódio, et omni mala voluntáte,", english: "From anger, and hatred, and every evil will,", start: 626.03, end: 632.61),
                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 632.61, end: 636.80),
                ChantLine(latin: "A spíritu fornicatiónis,", english: "From the spirit of fornication,", start: 637.09, end: 642.25),
                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 642.25, end: 646.50),
