                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 651.37, end: 655.71),
                ChantLine(latin: "A flagéllo terræmótus,", english: "From the scourge of earthquake,", start: 655.71, end: 660.33),
                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 660.33, end: 664.40),
                ChantLine(latin: "A peste, fame, et bello,", english: "From plague, famine, and war,", start: 664.73, end: 669.55),
                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 669.55, end: 673.90),
                ChantLine(latin: "A morte perpétua,", english: "From everlasting death,", start: 674.05, end: 678.29),
                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 678.29, end: 682.68),
                ChantLine(latin: "Per mystérium sanctæ Incarnatiónis tuæ,", english: "Through the mystery of Thy holy Incarnation,", start: 682.77, end: 689.17),
                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 689.17, end: 693.58),
                ChantLine(latin: "Per advéntum tuum,", english: "Through Thy coming,", start: 693.59, end: 697.47),
                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 697.47, end: 701.78),
                ChantLine(latin: "Per nativitátem tuam,", english: "Through Thy nativity,", start: 701.97, end: 706.61),
                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 706.61, end: 710.86),
                ChantLine(latin: "Per baptísmum et sanctum jejúnium tuum,", english: "Through Thy baptism and holy fasting,", start: 711.23, end: 717.19),
                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 717.19, end: 721.58),
                ChantLine(latin: "Per crucem et passiónem tuam,", english: "Through Thy cross and Passion,", start: 721.75, end: 726.87),
                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 726.87, end: 731.10),
                ChantLine(latin: "Per mortem et sepultúram tuam,", english: "Through Thy death and burial,", start: 731.53, end: 736.73),
                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 736.73, end: 741.20),
                ChantLine(latin: "Per sanctam resurrectiónem tuam,", english: "Through Thy holy Resurrection,", start: 741.25, end: 746.81),
                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 746.81, end: 751.16),
                ChantLine(latin: "Per admirábilem ascensiónem tuam,", english: "Through Thine admirable Ascension,", start: 751.49, end: 757.27),
                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 757.27, end: 761.66),
                ChantLine(latin: "Per advéntum Spíritus Sancti Parácliti,", english: "Through the coming of the Holy Ghost, the Paraclete,", start: 761.91, end: 767.77),
                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 767.77, end: 772.04),
                ChantLine(latin: "In die judícii,", english: "In the day of judgement,", start: 772.29, end: 776.61),
                ChantLine(latin: "líbera nos, Dómine.", english: "O Lord, deliver us.", start: 776.61, end: 781.12),
                ChantLine(latin: "Peccatóres,", english: "We sinners,", start: 781.77, end: 785.15),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 785.15, end: 789.57),
                ChantLine(latin: "Ut nobis parcas,", english: "That Thou wouldst spare us,", start: 789.57, end: 793.01),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 793.05, end: 797.69),
                ChantLine(latin: "Ut nobis indúlgeas,", english: "That Thou wouldst pardon us,", start: 797.69, end: 801.83),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 801.83, end: 806.36),
                ChantLine(latin: "Ut ad veram pœniténtiam nos perdúcere dignéris,", english: "That Thou wouldst vouchsafe to bring us to true penance,", start: 806.41, end: 812.85),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 812.85, end: 817.30),
                ChantLine(latin: "Ut Ecclésiam tuam sanctam régere et conserváre dignéris,", english: "That Thou wouldst vouchsafe to govern and preserve Thy holy Church,", start: 817.33, end: 826.05),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 826.05, end: 830.29),
                ChantLine(latin: "Ut domnum apostólicum et omnes ecclesiásticos órdines", english: "That our Apostolic Lord and all the orders of the Church", start: 830.29, end: 836.07),
                ChantLine(latin: "in sancta religióne conserváre dignéris,", english: "Thou wouldst vouchsafe to preserve in holy religion,", start: 836.07, end: 842.09),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 842.09, end: 846.37),
                ChantLine(latin: "Ut inimícos sanctæ Ecclésiæ humiliáre dignéris,", english: "That Thou wouldst vouchsafe to humble the enemies of holy Church,", start: 846.37, end: 854.25),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 854.25, end: 858.47),
                ChantLine(latin: "Ut régibus et princípibus christiánis", english: "That to Christian kings and princes", start: 858.47, end: 862.91),
                ChantLine(latin: "pacem et veram concórdiam donáre dignéris,", english: "Thou wouldst vouchsafe to give peace and true concord,", start: 862.91, end: 868.89),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 868.89, end: 873.27),
                ChantLine(latin: "Ut cuncto pópulo christiáno", english: "That to all Christian people", start: 873.27, end: 876.93),
                ChantLine(latin: "pacem et unitátem largíri dignéris,", english: "Thou wouldst vouchsafe to grant peace and unity,", start: 876.93, end: 882.31),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 882.31, end: 886.79),
                ChantLine(latin: "Ut omnes errántes ad unitátem Ecclésiæ revocáre,", english: "That Thou wouldst vouchsafe to call back all who stray to the unity of the Church,", start: 886.79, end: 892.27),
                ChantLine(latin: "et infidéles univérsos ad Evangélii lumen perdúcere dignéris,", english: "and to lead all unbelievers to the light of the Gospel,", start: 892.28, end: 900.31),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 900.31, end: 904.85),
                ChantLine(latin: "Ut nosmetípsos in tuo sancto servítio", english: "That in Thy holy service", start: 904.85, end: 909.15),
                ChantLine(latin: "confortáre et conserváre dignéris,", english: "Thou wouldst vouchsafe to strengthen and preserve us,", start: 909.15, end: 914.55),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 914.55, end: 918.79),
                ChantLine(latin: "Ut mentes nostras ad cæléstia desidéria érigas,", english: "That Thou wouldst lift up our minds to heavenly desires,", start: 918.79, end: 927.07),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 927.07, end: 931.25),
                ChantLine(latin: "Ut ómnibus benefactóribus nostris", english: "That to all our benefactors", start: 931.25, end: 935.35),
                ChantLine(latin: "sempitérna bona retríbuas,", english: "Thou wouldst render everlasting good things,", start: 935.38, end: 940.33),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 940.33, end: 944.75),
                ChantLine(latin: "Ut ánimas nostras, fratrum, propinquórum et benefactórum nostrórum", english: "That our souls, and those of our brethren, kinsfolk and benefactors,", start: 944.75, end: 952.67),
                ChantLine(latin: "ab ætérna damnatióne erípias,", english: "Thou wouldst deliver from eternal damnation,", start: 952.69, end: 958.29),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 958.29, end: 962.76),
                ChantLine(latin: "Ut fructus terræ", english: "That the fruits of the earth", start: 962.77, end: 965.29),
                ChantLine(latin: "dare et conserváre dignéris,", english: "Thou wouldst vouchsafe to give and preserve,", start: 965.29, end: 970.17),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 970.17, end: 974.45),
                ChantLine(latin: "Ut ómnibus fidélibus defúnctis", english: "That to all the faithful departed", start: 974.45, end: 978.43),
                ChantLine(latin: "réquiem ætérnam donáre dignéris,", english: "Thou wouldst vouchsafe to grant eternal rest,", start: 978.43, end: 983.73),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 983.73, end: 987.95),
                ChantLine(latin: "Ut nos exaudíre dignéris,", english: "That Thou wouldst vouchsafe graciously to hear us,", start: 987.95, end: 992.57),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 992.57, end: 997.03),
                ChantLine(latin: "Fili Dei,", english: "Son of God,", start: 997.03, end: 1000.23),
                ChantLine(latin: "te rogámus, audi nos.", english: "we beseech Thee, hear us.", start: 1000.23, end: 1004.60),
                ChantLine(latin: "Agnus Dei,", english: "Lamb of God,", start: 1005.01, end: 1008.05),
                ChantLine(latin: "qui tollis peccáta mundi,", english: "Who takest away the sins of the world,", start: 1008.06, end: 1012.29),
                ChantLine(latin: "parce nobis, Dómine.", english: "spare us, O Lord.", start: 1012.29, end: 1017.36),
                ChantLine(latin: "Agnus Dei, qui tollis peccáta mundi,", english: "Lamb of God, Who takest away the sins of the world,", start: 1017.39, end: 1024.97),
                ChantLine(latin: "exáudi nos Dómine.", english: "graciously hear us, O Lord.", start: 1024.97, end: 1029.72),
                ChantLine(latin: "Agnus Dei,", english: "Lamb of God,", start: 1029.81, end: 1032.85),
