            lines: [
                ChantLine(latin: "Roráte cæli désuper,", english: "Drop down dew, ye heavens, from above,", start: 0.31, end: 8.39),
                ChantLine(latin: "et nubes pluant justum.", english: "and let the clouds rain down the Just One.", start: 8.39, end: 14.52),
                ChantLine(latin: "Roráte cæli désuper,", english: "Drop down dew, ye heavens, from above,", start: 15.23, end: 23.15),
                ChantLine(latin: "et nubes pluant justum.", english: "and let the clouds rain down the Just One.", start: 23.15, end: 28.80),
                ChantLine(latin: "Ne irascáris Dómine,", english: "Be not angry, O Lord,", start: 29.87, end: 34.81),
                ChantLine(latin: "ne ultra memíneris iniquitátis:", english: "remember iniquity no longer:", start: 34.81, end: 41.29),
                ChantLine(latin: "ecce cívitas Sancti facta est desérta: Sion desérta facta est:", english: "behold, the city of the Holy One is become a desert: Sion is become a desert:", start: 41.29, end: 53.57),
                ChantLine(latin: "Jerúsalem desoláta est:", english: "Jerusalem is desolate:", start: 53.57, end: 61.14),
                ChantLine(latin: "domus sanctificatiónis tuæ et glóriæ tuæ,", english: "the house of Thy sanctification and of Thy glory,", start: 61.47, end: 69.94),
                ChantLine(latin: "ubi laudavérunt te patres nostri.", english: "where our fathers praised Thee.", start: 70.05, end: 78.56),
                ChantLine(latin: "Roráte cæli désuper,", english: "Drop down dew, ye heavens, from above,", start: 80.05, end: 88.13),
                ChantLine(latin: "et nubes pluant justum.", english: "and let the clouds rain down the Just One.", start: 88.13, end: 94.06),
                ChantLine(latin: "Peccávimus, et facti sumus tamquam immúndus nos,", english: "We have sinned, and are become as one unclean,", start: 95.17, end: 103.67),
                ChantLine(latin: "et cecídimus", english: "and we have fallen", start: 103.67, end: 107.29),
                ChantLine(latin: "quasi fólium univérsi:", english: "like a leaf, every one of us:", start: 107.29, end: 112.96),
                ChantLine(latin: "et iniquitátes nostræ quasi ventus abstulérunt nos:", english: "and our iniquities, like the wind, have carried us away:", start: 113.19, end: 122.52),
                ChantLine(latin: "abscondísti fáciem tuam a nobis,", english: "Thou hast hidden Thy face from us,", start: 122.85, end: 130.82),
                ChantLine(latin: "et allisísti nos in manu iniquitátis nostræ.", english: "and hast crushed us in the hand of our iniquity.", start: 131.39, end: 141.52),
                ChantLine(latin: "Roráte cæli désuper,", english: "Drop down dew, ye heavens, from above,", start: 142.63, end: 150.43),
                ChantLine(latin: "et nubes pluant justum.", english: "and let the clouds rain down the Just One.", start: 150.43, end: 156.34),
                ChantLine(latin: "Vide Dómine, afflictiónem pópuli tui,", english: "Behold, O Lord, the affliction of Thy people,", start: 157.61, end: 165.61),
                ChantLine(latin: "et mitte quem missúrus es:", english: "and send forth Him Whom Thou art to send:", start: 165.61, end: 172.32),
                ChantLine(latin: "emítte Agnum dominatórem terræ,", english: "send forth the Lamb, the ruler of the earth,", start: 172.39, end: 179.99),
                ChantLine(latin: "de Petra desérti ad montem fíliæ Sion:", english: "from the Rock of the desert to the mount of the daughter of Sion:", start: 179.99, end: 188.13),
                ChantLine(latin: "ut áuferat ipse jugum captivitátis nostræ.", english: "that He Himself may take away the yoke of our captivity.", start: 188.13, end: 197.50),
                ChantLine(latin: "Roráte cæli désuper,", english: "Drop down dew, ye heavens, from above,", start: 198.67, end: 206.51),
                ChantLine(latin: "et nubes pluant justum.", english: "and let the clouds rain down the Just One.", start: 206.51, end: 212.62),
                ChantLine(latin: "Consolámini,", english: "Be comforted,", start: 213.89, end: 216.79),
