            score: [
                ChantScorePart(file: "chant-creator-alme-siderum", caption: "Creator alme siderum", aspectRatio: 0.7705)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/creator-alme-siderum/")!,
            lines: [
                ChantLine(latin: "Creátor alme síderum, Ætérna lux credéntium,", english: "Gracious Creator of the stars, everlasting light of believers,", start: 0.37, end: 8.39),
                ChantLine(latin: "Jesu, Redémptor ómnium, Inténde votis súpplicum.", english: "Jesus, Redeemer of all, give ear to the prayers of Thy suppliants.", start: 8.39, end: 17.06),
                ChantLine(latin: "Qui dǽmonis ne fráudibus Períret orbis, ímpetu", english: "Thou who, lest the world should perish by the deceits of the devil, by the force", start: 18.35, end: 26.69),
                ChantLine(latin: "Amóris actus, lánguidi Mundi medéla factus es.", english: "of love wast moved to become the healing of a languishing world.", start: 26.69, end: 35.64),
                ChantLine(latin: "Commúne qui mundi nefas Ut expiáres, ad crucem", english: "Who, to atone for the common guilt of the world, to the Cross", start: 37.11, end: 45.89),
                ChantLine(latin: "E Vírginis sacrário Intácta prodis víctima.", english: "from the Virgin's sanctuary camest forth, a spotless Victim.", start: 45.89, end: 54.76),
                ChantLine(latin: "Cujus potéstas glóriæ, Noménque cum primum sonat,", english: "At whose glorious power, and at whose Name as soon as it sounds,", start: 56.09, end: 64.49),
                ChantLine(latin: "Et cǽlites et ínferi Treménte curvántur genu.", english: "both those in heaven and those below bow with trembling knee.", start: 64.49, end: 73.20),
                ChantLine(latin: "Te deprecámur, últimæ Magnum diéi Júdicem,", english: "We beseech Thee, the great Judge of the last day:", start: 74.27, end: 82.26),
                ChantLine(latin: "Armis supérnæ grátiæ Defénde nos ab hóstibus.", english: "with the arms of heavenly grace defend us from our foes.", start: 82.75, end: 91.02),
                ChantLine(latin: "Virtus, honor, laus, glória Deo Patri cum Fílio,", english: "Power, honour, praise and glory to God the Father with the Son,", start: 92.65, end: 101.41),
                ChantLine(latin: "Sancto simul Paráclito, In sæculórum sǽcula.", english: "together with the Holy Paraclete, for ever and ever.", start: 101.41, end: 111.04),
                ChantLine(latin: "Amen.", english: "Amen.", start: 112.17, end: 120.52)
            ]
        ),
        Chant(
            id: "veni_emmanuel",
