            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/puer-natus-in-bethlehem/")!,
            lines: [
                ChantLine(latin: "Puer natus in Béthlehem, allelúia:", english: "A Child is born in Bethlehem, alleluia:", start: 0.31, end: 7.61),
                ChantLine(latin: "Unde gaudet Jerúsalem, allelúia, allelúia.", english: "wherefore Jerusalem rejoices, alleluia, alleluia.", start: 7.61, end: 16.72),
                ChantLine(latin: "In cordis júbilo, Christum natum adorémus,", english: "With joy of heart let us adore Christ newly born,", start: 17.59, end: 25.90),
                ChantLine(latin: "Cum novo cántico.", english: "with a new song.", start: 26.13, end: 30.30),
                ChantLine(latin: "Assúmpsit carnem Fílius, allelúia,", english: "The Son hath taken flesh, alleluia,", start: 32.13, end: 39.25),
                ChantLine(latin: "Dei Patris altíssimus, allelúia, allelúia.", english: "of God the Father, the Most High, alleluia, alleluia.", start: 39.25, end: 48.32),
                ChantLine(latin: "In cordis júbilo, Christum natum adorémus,", english: "With joy of heart let us adore Christ newly born,", start: 48.99, end: 57.20),
                ChantLine(latin: "Cum novo cántico.", english: "with a new song.", start: 57.27, end: 62.02),
                ChantLine(latin: "Per Gabriélem núntium, allelúia,", english: "Through Gabriel the messenger, alleluia,", start: 63.19, end: 70.37),
                ChantLine(latin: "Virgo concépit Fílium, allelúia, allelúia.", english: "the Virgin conceived a Son, alleluia, alleluia.", start: 70.37, end: 79.44),
                ChantLine(latin: "In cordis júbilo, Christum natum adorémus,", english: "With joy of heart let us adore Christ newly born,", start: 80.37, end: 88.30),
                ChantLine(latin: "Cum novo cántico.", english: "with a new song.", start: 88.67, end: 93.36),
                ChantLine(latin: "Tamquam sponsus de thálamo, allelúia,", english: "As a bridegroom from his chamber, alleluia,", start: 94.85, end: 101.78),
                ChantLine(latin: "Procéssit Matris útero, allelúia, allelúia.", english: "He came forth from His Mother's womb, alleluia, alleluia.", start: 101.97, end: 110.38),
                ChantLine(latin: "In cordis júbilo, Christum natum adorémus,", english: "With joy of heart let us adore Christ newly born,", start: 111.59, end: 119.90),
                ChantLine(latin: "Cum novo cántico.", english: "with a new song.", start: 119.93, end: 124.56),
                ChantLine(latin: "Hic jacet in præsépio, allelúia:", english: "Here He lies in a manger, alleluia:", start: 125.97, end: 133.03),
                ChantLine(latin: "Qui regnat sine término, allelúia, allelúia.", english: "Who reigns without end, alleluia, alleluia.", start: 133.03, end: 141.70),
                ChantLine(latin: "In cordis júbilo, Christum natum adorémus,", english: "With joy of heart let us adore Christ newly born,", start: 142.63, end: 150.82),
                ChantLine(latin: "Cum novo cántico.", english: "with a new song.", start: 150.99, end: 155.24),
                ChantLine(latin: "Et Ángelus pastóribus, allelúia,", english: "And the Angel to the shepherds, alleluia,", start: 156.99, end: 164.01),
                ChantLine(latin: "Revélat quod sit Dóminus, allelúia, allelúia.", english: "reveals that He is the Lord, alleluia, alleluia.", start: 164.01, end: 172.92),
                ChantLine(latin: "In cordis júbilo, Christum natum adorémus,", english: "With joy of heart let us adore Christ newly born,", start: 173.67, end: 182.15),
                ChantLine(latin: "Cum novo cántico.", english: "with a new song.", start: 182.15, end: 186.44),
                ChantLine(latin: "Reges de Saba véniunt, allelúia,", english: "Kings come from Saba, alleluia,", start: 188.01, end: 195.31),
                ChantLine(latin: "Aurum, thus, myrrham ófferunt, allelúia, allelúia.", english: "gold, frankincense, myrrh they offer, alleluia, alleluia.", start: 195.31, end: 204.04),
                ChantLine(latin: "In cordis júbilo, Christum natum adorémus,", english: "With joy of heart let us adore Christ newly born,", start: 205.35, end: 213.72),
                ChantLine(latin: "Cum novo cántico.", english: "with a new song.", start: 213.93, end: 217.96),
                ChantLine(latin: "Intrántes domum ínvicem, allelúia,", english: "Entering the house one after another, alleluia,", start: 219.95, end: 227.17),
                ChantLine(latin: "Novum salútant Príncipem, allelúia, allelúia.", english: "they greet the new Prince, alleluia, alleluia.", start: 227.17, end: 236.44),
                ChantLine(latin: "In cordis júbilo, Christum natum adorémus,", english: "With joy of heart let us adore Christ newly born,", start: 237.15, end: 245.57),
                ChantLine(latin: "Cum novo cántico.", english: "with a new song.", start: 245.57, end: 250.98),
                ChantLine(latin: "De Matre natus Vírgine, allelúia,", english: "Born of a Virgin Mother, alleluia,", start: 251.69, end: 258.66),
                ChantLine(latin: "Qui lumen est de lúmine, allelúia, allelúia.", english: "He Who is Light of Light, alleluia, alleluia.", start: 258.89, end: 267.90),
                ChantLine(latin: "In cordis júbilo, Christum natum adorémus,", english: "With joy of heart let us adore Christ newly born,", start: 268.45, end: 276.99),
                ChantLine(latin: "Cum novo cántico.", english: "with a new song.", start: 276.99, end: 281.52),
                ChantLine(latin: "Sine serpéntis vúlnere, allelúia,", english: "Without the serpent's wound, alleluia,", start: 282.85, end: 290.09),
                ChantLine(latin: "De nostro venit sánguine, allelúia, allelúia.", english: "He came of our blood, alleluia, alleluia.", start: 290.09, end: 299.34),
