            score: [
                ChantScorePart(file: "chant-jesu-redemptor-omnium", caption: "Jesu Redemptor omnium", aspectRatio: 0.5821)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/jesu-redemptor-omnium/")!,
            lines: [
                ChantLine(latin: "Jesu Redémptor ómnium,", english: "Jesus, Redeemer of all,", start: 0.37, end: 6.73),
                ChantLine(latin: "Quem lucis ante oríginem,", english: "Whom, before the beginning of light,", start: 6.73, end: 13.69),
                ChantLine(latin: "Parem patérnæ glóriæ,", english: "equal to the Father's glory,", start: 13.69, end: 19.37),
                ChantLine(latin: "Pater suprémus édidit.", english: "the Father most high begot.", start: 19.37, end: 25.10),
                ChantLine(latin: "Tu lumen et splendor Patris,", english: "Thou light and splendour of the Father,", start: 26.79, end: 32.98),
                ChantLine(latin: "Tu spes perénnis ómnium:", english: "Thou everlasting hope of all,", start: 33.17, end: 40.27),
                ChantLine(latin: "Inténde quas fundunt preces", english: "give ear to the prayers poured forth", start: 40.27, end: 46.53),
                ChantLine(latin: "Tui per orbem sérvuli.", english: "by Thy servants throughout the world.", start: 46.53, end: 52.50),
                ChantLine(latin: "Meménto, rerum Cónditor,", english: "Remember, O Maker of all things,", start: 53.83, end: 59.93),
                ChantLine(latin: "Nostri quod olim córporis,", english: "that once, of our body,", start: 59.93, end: 67.41),
                ChantLine(latin: "Sacráta ab alvo Vírginis", english: "from the hallowed womb of the Virgin,", start: 67.41, end: 73.29),
                ChantLine(latin: "Nascéndo, formam súmpseris.", english: "being born, Thou didst take the form.", start: 73.29, end: 79.34),
                ChantLine(latin: "Testátur hoc præsens dies,", english: "This present day bears witness,", start: 81.45, end: 87.91),
                ChantLine(latin: "Currens per anni círculum,", english: "running its course through the circle of the year,", start: 87.91, end: 95.45),
                ChantLine(latin: "Quod solus e sinu Patris", english: "that Thou alone, from the bosom of the Father,", start: 95.45, end: 101.38),
                ChantLine(latin: "Mundi salus advéneris.", english: "didst come, the salvation of the world.", start: 101.63, end: 107.82),
                ChantLine(latin: "Hunc astra, tellus, ǽquora,", english: "Him the stars, the earth, the seas,", start: 109.43, end: 115.75),
                ChantLine(latin: "Hunc omne quod cælo subest,", english: "Him all that is beneath the heavens,", start: 115.75, end: 123.45),
                ChantLine(latin: "Salútis auctórem novæ", english: "the Author of a new salvation,", start: 123.45, end: 129.81),
                ChantLine(latin: "Novo salútat cántico.", english: "greet with a new song.", start: 129.81, end: 136.54),
                ChantLine(latin: "Et nos, beáta quos sacri", english: "And we, whom the blessed stream", start: 137.25, end: 143.32),
                ChantLine(latin: "Rigávit unda sánguinis,", english: "of sacred Blood hath watered,", start: 143.49, end: 151.01),
                ChantLine(latin: "Natális ob diem tui,", english: "for the day of Thy birth", start: 151.01, end: 157.08),
                ChantLine(latin: "Hymni tribútum sólvimus.", english: "pay the tribute of a hymn.", start: 157.19, end: 163.32),
                ChantLine(latin: "Jesu, tibi sit glória,", english: "Jesus, to Thee be glory,", start: 165.01, end: 171.39),
                ChantLine(latin: "Qui natus es de Vírgine,", english: "Who wast born of the Virgin,", start: 171.39, end: 178.67),
                ChantLine(latin: "Cum Patre et almo Spíritu,", english: "with the Father and the loving Spirit,", start: 178.67, end: 184.71),
                ChantLine(latin: "In sempitérna sǽcula.", english: "unto everlasting ages.", start: 184.71, end: 191.62),
                ChantLine(latin: "Amen.", english: "Amen.", start: 192.31, end: 196.78)
            ]
        ),
