                ChantLine(latin: "Déxtera Patris, lapis anguláris,", english: "Right hand of the Father, corner-stone,", start: 63.33, end: 71.03),
                ChantLine(latin: "via salútis, jánua cæléstis,", english: "way of salvation, gate of heaven,", start: 71.03, end: 78.01),
                ChantLine(latin: "áblue nostri máculas delícti.", english: "wash away the stains of our sin.", start: 78.01, end: 85.26),
                ChantLine(latin: "Atténde Dómine, et miserére, quia peccávimus tibi.", english: "Hearken, O Lord, and have mercy, for we have sinned against Thee.", start: 86.27, end: 98.28),
                ChantLine(latin: "Rogámus, Deus, tuam majestátem:", english: "We beseech Thy majesty, O God;", start: 99.35, end: 107.05),
                ChantLine(latin: "áuribus sacris gémitus exáudi:", english: "with Thy holy ears hear our groaning;", start: 107.05, end: 113.99),
                ChantLine(latin: "crímina nostra plácidus indúlge.", english: "graciously pardon our crimes.", start: 113.99, end: 121.88),
                ChantLine(latin: "Atténde Dómine, et miserére,", english: "Hearken, O Lord, and have mercy,", start: 122.05, end: 128.63),
                ChantLine(latin: "quia peccávimus tibi.", english: "for we have sinned against Thee.", start: 128.63, end: 134.14),
                ChantLine(latin: "Tibi fatémur crímina admíssa:", english: "To Thee we confess the sins we have committed;", start: 135.41, end: 142.77),
                ChantLine(latin: "contríto corde pándimus occúlta:", english: "with contrite heart we lay bare what was hidden;", start: 142.77, end: 149.85),
                ChantLine(latin: "tua, Redémptor, píetas ignóscat.", english: "may Thy loving-kindness, O Redeemer, forgive.", start: 149.85, end: 157.56),
                ChantLine(latin: "Atténde Dómine, et miserére, quia peccávimus tibi.", english: "Hearken, O Lord, and have mercy, for we have sinned against Thee.", start: 158.09, end: 170.06),
                ChantLine(latin: "Ínnocens captus, nec repúgnans ductus,", english: "Seized though innocent, led away unresisting,", start: 171.23, end: 178.73),
                ChantLine(latin: "téstibus falsis pro ímpiis damnátus:", english: "condemned by false witnesses for the wicked;", start: 178.73, end: 185.95),
                ChantLine(latin: "quos redemísti, tu consérva, Christe.", english: "keep, O Christ, those whom Thou hast redeemed.", start: 185.95, end: 193.58),
                ChantLine(latin: "Atténde Dómine, et miserére,", english: "Hearken, O Lord, and have mercy,", start: 194.31, end: 200.89),
                ChantLine(latin: "quia peccávimus tibi.", english: "for we have sinned against Thee.", start: 200.89, end: 207.56)
            ]
        ),
