                ChantLine(latin: "Scrutátor alme córdium,", english: "O gracious Searcher of hearts,", start: 198.37, end: 202.91),
                ChantLine(latin: "Infírma tu scis vírium;", english: "Thou knowest the weakness of our strength;", start: 202.91, end: 207.93),
                ChantLine(latin: "Ad te revérsis éxhibe Remissiónis grátiam.", english: "show to those who return to Thee the grace of forgiveness.", start: 207.93, end: 217.44),
                ChantLine(latin: "Parce Dómine,", english: "Spare, O Lord,", start: 218.67, end: 222.69),
                ChantLine(latin: "parce pópulo tuo:", english: "spare Thy people;", start: 222.69, end: 228.41),
                ChantLine(latin: "ne in ætérnum", english: "be not for ever", start: 228.41, end: 231.67),
                ChantLine(latin: "irascáris nobis.", english: "angry with us.", start: 231.67, end: 237.40)
            ]
