        Chant(
            id: "miserere",
            groupID: "lent",
            latinTitle: "Miserere Mei, Deus",
            englishTitle: "Psalm 50 · Have Mercy on Me",
            setting: nil,
            detail: "David's psalm of repentance",
            prayerIDs: ["miserere"],
            duration: 320.1,
            score: [
                ChantScorePart(file: "chant-miserere-mei-deus", caption: "Miserere mei Deus", aspectRatio: 0.2883)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/miserere-mei-deus/")!,
            lines: [
                ChantLine(latin: "Miserére mei Deus,", english: "Have mercy on me, O God,", start: 0.43, end: 5.85),
                ChantLine(latin: "secúndum magnam misericórdiam tuam.", english: "according to Thy great mercy.", start: 5.85, end: 13.75),
                ChantLine(latin: "Et secúndum multitúdinem miseratiónum tuárum,", english: "And according to the multitude of Thy tender mercies", start: 13.75, end: 21.23),
                ChantLine(latin: "dele iniquitátem meam.", english: "blot out my iniquity.", start: 21.23, end: 28.14),
                ChantLine(latin: "Amplius lava me ab iniquitáte mea:", english: "Wash me yet more from my iniquity,", start: 28.15, end: 35.09),
                ChantLine(latin: "et a peccáto meo munda me.", english: "and cleanse me from my sin.", start: 35.09, end: 41.59),
                ChantLine(latin: "Quóniam iniquitátem meam ego cognósco:", english: "For I know my iniquity,", start: 41.59, end: 48.37),
                ChantLine(latin: "et peccátum meum contra me est semper.", english: "and my sin is always before me.", start: 48.37, end: 56.08),
                ChantLine(latin: "Tibi soli peccávi, et malum coram te feci:", english: "To Thee only have I sinned, and have done evil before Thee:", start: 56.11, end: 63.37),
                ChantLine(latin: "ut justificéris in sermónibus tuis, et vincas cum judicáris.", english: "that Thou mayst be justified in Thy words, and mayst overcome when Thou art judged.", start: 63.37, end: 72.99),
                ChantLine(latin: "Ecce enim in iniquitátibus concéptus sum:", english: "For behold I was conceived in iniquities:", start: 72.99, end: 80.11),
                ChantLine(latin: "et in peccátis concépit me mater mea.", english: "and in sins did my mother conceive me.", start: 80.11, end: 87.93),
                ChantLine(latin: "Ecce enim veritátem dilexísti:", english: "For behold Thou hast loved truth:", start: 87.93, end: 94.87),
                ChantLine(latin: "incérta et occúlta sapiéntiæ tuæ manifestásti mihi.", english: "the uncertain and hidden things of Thy wisdom Thou hast made manifest to me.", start: 94.87, end: 103.78),
                ChantLine(latin: "Aspérges me hyssópo, et mundábor:", english: "Thou shalt sprinkle me with hyssop, and I shall be cleansed:", start: 104.99, end: 111.47),
                ChantLine(latin: "lavábis me, et super nivem dealbábor.", english: "Thou shalt wash me, and I shall be made whiter than snow.", start: 111.47, end: 118.66),
                ChantLine(latin: "Audítui meo dabis gáudium et lætítiam:", english: "To my hearing Thou shalt give joy and gladness:", start: 119.23, end: 126.59),
                ChantLine(latin: "et exsultábunt ossa humiliáta.", english: "and the bones that have been humbled shall rejoice.", start: 126.59, end: 133.97),
                ChantLine(latin: "Avérte fáciem tuam a peccátis meis:", english: "Turn away Thy face from my sins,", start: 133.97, end: 140.85),
                ChantLine(latin: "et omnes iniquitátes meas dele.", english: "and blot out all my iniquities.", start: 140.85, end: 148.06),
                ChantLine(latin: "Cor mundum crea in me, Deus:", english: "Create a clean heart in me, O God:", start: 148.45, end: 153.99),
                ChantLine(latin: "et spíritum rectum ínnova in viscéribus meis.", english: "and renew a right spirit within my bowels.", start: 153.99, end: 162.20),
                ChantLine(latin: "Ne projícias me a fácie tua:", english: "Cast me not away from Thy face:", start: 162.51, end: 169.17),
                ChantLine(latin: "et spíritum sanctum tuum ne áuferas a me.", english: "and take not Thy holy spirit from me.", start: 169.17, end: 177.67),
                ChantLine(latin: "Redde mihi lætítiam salutáris tui:", english: "Restore unto me the joy of Thy salvation,", start: 177.67, end: 184.83),
                ChantLine(latin: "et spíritu principáli confírma me.", english: "and strengthen me with a perfect spirit.", start: 184.83, end: 192.38),
                ChantLine(latin: "Docébo iníquos vias tuas:", english: "I will teach the unjust Thy ways:", start: 192.65, end: 198.93),
                ChantLine(latin: "et ímpii ad te converténtur.", english: "and the wicked shall be converted to Thee.", start: 198.93, end: 205.56),
                ChantLine(latin: "Líbera me de sanguínibus, Deus, Deus salútis meæ:", english: "Deliver me from blood, O God, Thou God of my salvation:", start: 206.01, end: 213.93),
                ChantLine(latin: "et exsultábit lingua mea justítiam tuam.", english: "and my tongue shall extol Thy justice.", start: 213.93, end: 222.28),
                ChantLine(latin: "Dómine, lábia mea apéries:", english: "O Lord, Thou wilt open my lips:", start: 222.53, end: 228.99),
                ChantLine(latin: "et os meum annuntiábit laudem tuam.", english: "and my mouth shall declare Thy praise.", start: 228.99, end: 236.79),
                ChantLine(latin: "Quóniam si voluísses sacrifícium, dedíssem útique:", english: "For if Thou hadst desired sacrifice, I would indeed have given it:", start: 236.79, end: 245.01),
                ChantLine(latin: "holocáustis non delectáberis.", english: "with burnt offerings Thou wilt not be delighted.", start: 245.01, end: 251.46),
                ChantLine(latin: "Sacrifícium Deo spíritus contribulátus:", english: "A sacrifice to God is an afflicted spirit:", start: 251.95, end: 259.57),
                ChantLine(latin: "cor contrítum et humiliátum, Deus, non despícies.", english: "a contrite and humbled heart, O God, Thou wilt not despise.", start: 259.57, end: 267.76),
                ChantLine(latin: "Benígne fac, Dómine, in bona voluntáte tua Sion:", english: "Deal favourably, O Lord, in Thy good will with Sion:", start: 268.23, end: 276.73),
                ChantLine(latin: "ut ædificéntur muri Jerúsalem.", english: "that the walls of Jerusalem may be built up.", start: 276.73, end: 284.42),
                ChantLine(latin: "Tunc acceptábis sacrifícium justítiæ, oblatiónes, et holocáusta:", english: "Then shalt Thou accept the sacrifice of justice, oblations and whole burnt offerings:", start: 284.83, end: 294.79),
                ChantLine(latin: "tunc impónent super altáre tuum vítulos.", english: "then shall they lay calves upon Thy altar.", start: 294.79, end: 302.62),
                ChantLine(latin: "Miserére mei Deus:", english: "Have mercy on me, O God:", start: 303.37, end: 309.11),
                ChantLine(latin: "miserére mei.", english: "have mercy on me.", start: 309.11, end: 314.62)
            ]
        ),
        Chant(
            id: "vexilla_regis",
            groupID: "lent",
            latinTitle: "Vexilla Regis",
            englishTitle: "The Banners of the King",
            setting: nil,
            detail: "The evening hymn of the last two weeks of Lent",
            prayerIDs: [],
            duration: 205.1,
            score: [
                ChantScorePart(file: "chant-vexilla-regis-prodeunt", caption: "Vexilla Regis prodeunt", aspectRatio: 0.5869)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/vexilla-regis-prodeunt/")!,
            lines: [
                ChantLine(latin: "Vexílla Regis pródeunt:", english: "The banners of the King go forth;", start: 0.27, end: 7.17),
                ChantLine(latin: "Fulget Crucis mystérium,", english: "the mystery of the Cross shines out,", start: 7.17, end: 12.84),
                ChantLine(latin: "Qua vita mortem pértulit,", english: "whereon Life endured death,", start: 13.13, end: 19.11),
                ChantLine(latin: "Et morte vitam prótulit.", english: "and by death brought forth life.", start: 19.11, end: 26.12),
                ChantLine(latin: "Quæ vulneráta lánceæ", english: "Wounded by the spear's", start: 27.89, end: 34.63),
                ChantLine(latin: "Mucróne diro, críminum", english: "cruel point, that from the filth of our sins", start: 34.63, end: 40.08),
                ChantLine(latin: "Ut nos laváret sórdibus,", english: "it might wash us,", start: 40.75, end: 46.85),
                ChantLine(latin: "Manávit unda et sánguine.", english: "it poured forth water and blood.", start: 46.85, end: 54.26),
                ChantLine(latin: "Impléta sunt quæ cóncinit", english: "Fulfilled are the things which David", start: 56.09, end: 62.52),
                ChantLine(latin: "David fidéli cármine,", english: "sang in faithful verse,", start: 62.79, end: 68.24),
                ChantLine(latin: "Dicéndo natiónibus:", english: "telling the nations:", start: 68.97, end: 74.95),
                ChantLine(latin: "Regnávit a ligno Deus.", english: "God hath reigned from the Tree.", start: 74.95, end: 82.16),
                ChantLine(latin: "Arbor decóra et fúlgida,", english: "O Tree, beautiful and shining,", start: 84.11, end: 90.69),
                ChantLine(latin: "Ornáta Regis púrpura,", english: "adorned with the purple of the King,", start: 90.69, end: 96.50),
                ChantLine(latin: "Elécta digno stípite", english: "chosen from a worthy stock", start: 96.61, end: 102.59),
                ChantLine(latin: "Tam sancta membra tángere.", english: "to touch limbs so holy.", start: 102.59, end: 109.82),
                ChantLine(latin: "Beáta, cujus bráchiis", english: "Blessed Tree, upon whose arms", start: 111.43, end: 118.32),
                ChantLine(latin: "Prétium pepéndit sǽculi:", english: "hung the ransom of the world;", start: 118.35, end: 123.80),
                ChantLine(latin: "Statéra facta córporis,", english: "it was made the balance of His Body,", start: 124.55, end: 130.57),
                ChantLine(latin: "Tulítque prædam tártari.", english: "and took away the prey of hell.", start: 130.57, end: 137.74),
                ChantLine(latin: "O Crux ave, spes única,", english: "Hail, O Cross, our only hope!", start: 139.35, end: 145.91),
                ChantLine(latin: "Hoc Passiónis témpore", english: "In this time of the Passion", start: 145.91, end: 151.34),
                ChantLine(latin: "Piis adáuge grátiam,", english: "increase grace in the devout,", start: 151.79, end: 157.41),
                ChantLine(latin: "Reísque dele crímina.", english: "and blot out the crimes of the guilty.", start: 157.41, end: 164.72),
                ChantLine(latin: "Te fons salútis Trínitas,", english: "Thee, O Trinity, fount of salvation,", start: 166.51, end: 173.11),
                ChantLine(latin: "Colláudet omnis spíritus:", english: "let every spirit praise;", start: 173.11, end: 178.70),
                ChantLine(latin: "Quibus Crucis victóriam", english: "to those to whom the victory of the Cross", start: 179.05, end: 185.05),
                ChantLine(latin: "Largíris, adde prǽmium.", english: "Thou givest, add the reward.", start: 185.05, end: 192.38),
                ChantLine(latin: "Amen.", english: "Amen.", start: 194.23, end: 199.30)
            ]
        ),
        Chant(
            id: "audi_benigne",
            groupID: "lent",
            latinTitle: "Audi Benigne Conditor",
            englishTitle: "O Kind Creator, Bow Thine Ear",
            setting: nil,
            detail: "The evening hymn of Lent",
            prayerIDs: [],
            duration: 135.0,
            score: [
                ChantScorePart(file: "chant-audi-benigne-conditor-web-1", caption: "Audi benigne Conditor", aspectRatio: 0.8842)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/audi-benigne-conditor/")!,
            lines: [
                ChantLine(latin: "Audi, benígne Cónditor, Nostras preces cum flétibus,", english: "Hear, kind Creator, our prayers poured out with weeping", start: 0.25, end: 12.59, part: 0),
                ChantLine(latin: "In hoc sacro jejúnio Fusas quadragenário.", english: "in this holy fast of forty days.", start: 12.59, end: 24.14, part: 0),
                ChantLine(latin: "Scrutátor alme córdium,", english: "Kind Searcher of hearts,", start: 24.73, end: 30.81, part: 0),
                ChantLine(latin: "Infírma tu scis vírium:", english: "Thou knowest how weak our strength is:", start: 30.81, end: 37.07, part: 0),
                ChantLine(latin: "Ad te revérsis éxhibe Remissiónis grátiam.", english: "to those who have turned back to Thee show the grace of pardon.", start: 37.07, end: 49.40, part: 0),
                ChantLine(latin: "Multum quidem peccávimus,", english: "Much indeed have we sinned,", start: 49.91, end: 55.73, part: 0),
                ChantLine(latin: "Sed parce confiténtibus:", english: "but spare us who confess it:", start: 55.73, end: 62.09, part: 0),
                ChantLine(latin: "Ad nóminis laudem tui, Confer medélam lánguidis.", english: "for the praise of Thy name bring healing to the sick.", start: 62.09, end: 73.78, part: 0),
                ChantLine(latin: "Concéde nostrum cónteri", english: "Grant that our body", start: 75.15, end: 81.03, part: 0),
                ChantLine(latin: "Corpus per abstinéntiam, Culpæ ut relínquant pábulum Jejúna corda críminum.", english: "be subdued by abstinence, that our fasting hearts may forsake the food of sin.", start: 81.03, end: 98.56, part: 0),
                ChantLine(latin: "Præsta beáta Trínitas, Concéde simplex Únitas:", english: "Grant, O blessed Trinity, grant, O simple Unity,", start: 99.87, end: 112.03, part: 0),
                ChantLine(latin: "Ut fructuósa sint tuis Jejuniórum múnera.", english: "that the gifts of fasting may bear fruit for Thine own.", start: 112.03, end: 124.16, part: 0),
                ChantLine(latin: "Amen.", english: "Amen.", start: 124.77, end: 130.76, part: 0)
            ]
        ),
        Chant(
            id: "o_vos_omnes",
