                ChantLine(latin: "atténdite, et vidéte:", english: "attend, and see", start: 12.93, end: 21.26, part: 0),
                ChantLine(latin: "Si est dolor símilis", english: "if there be any sorrow", start: 21.85, end: 33.26, part: 0),
                ChantLine(latin: "sicut dolor meus.", english: "like to my sorrow.", start: 33.71, end: 46.86, part: 0),
                ChantLine(latin: "Atténdite, univérsi pópuli,", english: "Attend, all ye people,", start: 48.19, end: 61.86, part: 0),
                ChantLine(latin: "et vidéte dolórem meum.", english: "and see my sorrow.", start: 62.43, end: 79.68, part: 0),
                ChantLine(latin: "Si est dolor símilis", english: "If there be any sorrow", start: 80.79, end: 92.20, part: 0),
                ChantLine(latin: "sicut dolor meus.", english: "like to my sorrow.", start: 92.63, end: 105.86, part: 0)
            ]
        ),
        Chant(
            id: "victimae_paschali",
            groupID: "easter",
            latinTitle: "Victimæ Paschali Laudes",
            englishTitle: "Praises to the Paschal Victim",
            setting: nil,
            detail: "The feast poem of Easter Sunday",
            prayerIDs: [],
            duration: 114.0,
            score: [
                ChantScorePart(file: "chant-victimae-paschali-laudes", caption: "Victimae paschali laudes", aspectRatio: 0.8993)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/victimae-paschali-laudes/")!,
            lines: [
                ChantLine(latin: "Víctimæ pascháli laudes", english: "Praises to the Paschal Victim", start: 0.41, end: 4.81),
                ChantLine(latin: "ímmolent Christiáni.", english: "let Christians offer.", start: 4.81, end: 9.16),
                ChantLine(latin: "Agnus redémit oves:", english: "The Lamb hath redeemed the sheep;", start: 9.17, end: 13.21),
                ChantLine(latin: "Christus ínnocens Patri", english: "Christ, the innocent, unto the Father", start: 13.21, end: 17.61),
                ChantLine(latin: "reconciliávit", english: "hath reconciled", start: 17.61, end: 21.35),
                ChantLine(latin: "peccatóres.", english: "sinners.", start: 21.35, end: 24.68),
                ChantLine(latin: "Mors et vita duéllo conflixére mirándo:", english: "Death and life have contended in a wondrous combat;", start: 25.43, end: 33.65),
                ChantLine(latin: "dux vitæ mórtuus,", english: "the Prince of life, who died,", start: 33.65, end: 37.29),
                ChantLine(latin: "regnat vivus.", english: "reigns alive.", start: 37.30, end: 41.24),
                ChantLine(latin: "Dic nobis María, quid vidísti", english: "Tell us, Mary, what didst thou see", start: 42.29, end: 47.57),
                ChantLine(latin: "in via?", english: "on the way?", start: 47.57, end: 51.06),
                ChantLine(latin: "Sepúlcrum Christi vivéntis,", english: "The tomb of the living Christ,", start: 51.49, end: 56.35),
                ChantLine(latin: "et glóriam vidi resurgéntis:", english: "and I saw the glory of His rising;", start: 56.35, end: 61.98),
                ChantLine(latin: "Angélicos testes, sudárium, et vestes.", english: "the angelic witnesses, the napkin, and the garments.", start: 62.39, end: 70.84),
                ChantLine(latin: "Surréxit Christus spes mea:", english: "Christ my hope is risen;", start: 71.99, end: 76.71),
                ChantLine(latin: "præcédet suos in Galilǽam.", english: "He will go before His own into Galilee.", start: 76.71, end: 82.62),
                ChantLine(latin: "Scimus Christum surrexísse", english: "We know that Christ is risen", start: 83.07, end: 87.53),
                ChantLine(latin: "a mórtuis vere:", english: "truly from the dead;", start: 87.53, end: 91.60),
                ChantLine(latin: "tu nobis, victor Rex,", english: "on us, O victorious King,", start: 91.73, end: 95.91),
                ChantLine(latin: "miserére.", english: "have mercy.", start: 95.91, end: 100.20),
                ChantLine(latin: "Amen. Allelúia.", english: "Amen. Alleluia.", start: 101.39, end: 109.10)
            ]
        ),
        Chant(
