                ChantLine(latin: "allelúia.", english: "alleluia.", start: 15.73, end: 20.54),
                ChantLine(latin: "O fílii et fíliæ,", english: "O sons and daughters,", start: 20.91, end: 26.01),
                ChantLine(latin: "Rex cæléstis, Rex glóriæ,", english: "the King of heaven, the King of glory,", start: 26.02, end: 31.01),
                ChantLine(latin: "Morte surréxit hódie,", english: "hath risen from death today.", start: 31.01, end: 36.35),
                ChantLine(latin: "Allelúia.", english: "Alleluia.", start: 36.35, end: 40.44),
                ChantLine(latin: "Allelúia, allelúia,", english: "Alleluia, alleluia,", start: 40.73, end: 46.07),
                ChantLine(latin: "allelúia.", english: "alleluia.", start: 46.07, end: 50.84),
                ChantLine(latin: "Et mane prima sábbati,", english: "And early on the first day of the week", start: 51.17, end: 56.19),
                ChantLine(latin: "Ad óstium monuménti", english: "to the door of the tomb", start: 56.19, end: 61.23),
                ChantLine(latin: "Accessérunt discípuli,", english: "the disciples came.", start: 61.23, end: 66.33),
                ChantLine(latin: "Allelúia.", english: "Alleluia.", start: 66.33, end: 70.74),
                ChantLine(latin: "Allelúia, allelúia,", english: "Alleluia, alleluia,", start: 71.03, end: 76.47),
                ChantLine(latin: "allelúia.", english: "alleluia.", start: 76.47, end: 81.04),
                ChantLine(latin: "Et María Magdaléne,", english: "And Mary Magdalen,", start: 81.47, end: 86.61),
                ChantLine(latin: "Et Jacóbi, et Salóme,", english: "and Mary of James, and Salome,", start: 86.61, end: 91.55),
                ChantLine(latin: "Venérunt corpus úngere,", english: "came to anoint the Body.", start: 91.55, end: 96.87),
                ChantLine(latin: "Allelúia.", english: "Alleluia.", start: 96.87, end: 100.82),
                ChantLine(latin: "Allelúia, allelúia,", english: "Alleluia, alleluia,", start: 101.21, end: 106.61),
                ChantLine(latin: "allelúia.", english: "alleluia.", start: 106.61, end: 110.58),
                ChantLine(latin: "In albis sedens Ángelus", english: "An Angel sitting in white", start: 111.39, end: 116.59),
                ChantLine(latin: "Prædíxit muliéribus:", english: "foretold to the women:", start: 116.59, end: 121.65),
                ChantLine(latin: "In Galilǽa est Dóminus,", english: "The Lord is in Galilee.", start: 121.65, end: 126.73),
                ChantLine(latin: "Allelúia.", english: "Alleluia.", start: 126.73, end: 130.92),
