                ChantLine(latin: "Cucúrrit Petro cítius,", english: "ran more swiftly than Peter,", start: 146.47, end: 151.45),
                ChantLine(latin: "Monuménto venit prius,", english: "and came first to the tomb.", start: 151.45, end: 156.67),
                ChantLine(latin: "Allelúia.", english: "Alleluia.", start: 156.67, end: 160.94),
