                ChantLine(latin: "allelúia.", english: "alleluia.", start: 166.83, end: 171.88),
                ChantLine(latin: "Discípulis adstántibus,", english: "As the disciples stood by,", start: 172.01, end: 177.29),
                ChantLine(latin: "In médio stetit Christus,", english: "Christ stood in their midst,", start: 177.29, end: 182.43),
                ChantLine(latin: "Dicens: Pax vobis ómnibus,", english: "saying: Peace be to you all.", start: 182.43, end: 187.73),
                ChantLine(latin: "Allelúia.", english: "Alleluia.", start: 187.73, end: 192.20),
                ChantLine(latin: "Allelúia, allelúia,", english: "Alleluia, alleluia,", start: 192.57, end: 198.07),
                ChantLine(latin: "allelúia.", english: "alleluia.", start: 198.07, end: 202.46),
                ChantLine(latin: "Ut intelléxit Dídymus,", english: "When Didymus understood", start: 203.17, end: 208.37),
                ChantLine(latin: "Quia surréxerat Jesus,", english: "that Jesus had risen,", start: 208.37, end: 213.47),
                ChantLine(latin: "Remánsit fere dúbius,", english: "he remained still in doubt.", start: 213.47, end: 218.53),
                ChantLine(latin: "Allelúia.", english: "Alleluia.", start: 218.53, end: 223.16),
                ChantLine(latin: "Allelúia, allelúia,", english: "Alleluia, alleluia,", start: 223.45, end: 228.75),
                ChantLine(latin: "allelúia.", english: "alleluia.", start: 228.75, end: 233.30),
                ChantLine(latin: "Vide, Thoma, vide latus,", english: "See, Thomas, see My side,", start: 233.97, end: 238.91),
                ChantLine(latin: "Vide pedes, vide manus,", english: "see My feet, see My hands;", start: 238.91, end: 243.71),
                ChantLine(latin: "Noli esse incrédulus,", english: "be not faithless.", start: 243.71, end: 248.91),
                ChantLine(latin: "Allelúia.", english: "Alleluia.", start: 248.91, end: 253.58),
                ChantLine(latin: "Allelúia, allelúia,", english: "Alleluia, alleluia,", start: 253.75, end: 258.83),
                ChantLine(latin: "allelúia.", english: "alleluia.", start: 258.83, end: 263.42),
                ChantLine(latin: "Quando Thomas Christi latus,", english: "When Thomas the side of Christ,", start: 263.81, end: 268.85),
                ChantLine(latin: "Pedes vidit atque manus,", english: "His feet and His hands had seen,", start: 268.85, end: 273.63),
                ChantLine(latin: "Dixit: Tu es Deus meus,", english: "he said: Thou art my God.", start: 273.63, end: 278.63),
                ChantLine(latin: "Allelúia.", english: "Alleluia.", start: 278.63, end: 282.86),
                ChantLine(latin: "Allelúia, allelúia,", english: "Alleluia, alleluia,", start: 283.41, end: 288.61),
                ChantLine(latin: "allelúia.", english: "alleluia.", start: 288.61, end: 293.08),
                ChantLine(latin: "Beáti qui non vidérunt,", english: "Blessed are they that have not seen,", start: 293.61, end: 298.63),
                ChantLine(latin: "Et fírmiter credidérunt,", english: "and have firmly believed;", start: 298.63, end: 303.55),
                ChantLine(latin: "Vitam ætérnam habébunt,", english: "they shall have life everlasting.", start: 303.55, end: 308.61),
                ChantLine(latin: "Allelúia.", english: "Alleluia.", start: 308.61, end: 312.94),
                ChantLine(latin: "Allelúia, allelúia,", english: "Alleluia, alleluia,", start: 313.15, end: 318.25),
                ChantLine(latin: "allelúia.", english: "alleluia.", start: 318.25, end: 322.30),
                ChantLine(latin: "In hoc festo sanctíssimo", english: "On this most holy feast", start: 323.01, end: 328.25),
                ChantLine(latin: "Sit laus et jubilátio,", english: "be praise and jubilation:", start: 328.25, end: 333.19),
                ChantLine(latin: "Benedicámus Dómino,", english: "let us bless the Lord.", start: 333.19, end: 338.31),
                ChantLine(latin: "Allelúia.", english: "Alleluia.", start: 338.31, end: 342.46),
                ChantLine(latin: "Allelúia, allelúia,", english: "Alleluia, alleluia,", start: 342.99, end: 348.29),
                ChantLine(latin: "allelúia.", english: "alleluia.", start: 348.29, end: 352.56),
                ChantLine(latin: "Ex quibus nos humíllimas", english: "For these things, most humble,", start: 353.23, end: 358.41),
                ChantLine(latin: "Devótas atque débitas", english: "devout and due,", start: 358.41, end: 363.53),
                ChantLine(latin: "Deo dicámus grátias,", english: "let us give thanks to God.", start: 363.53, end: 368.97),
                ChantLine(latin: "Allelúia.", english: "Alleluia.", start: 368.97, end: 373.62),
                ChantLine(latin: "Allelúia, allelúia,", english: "Alleluia, alleluia,", start: 373.85, end: 379.61),
                ChantLine(latin: "allelúia.", english: "alleluia.", start: 379.61, end: 385.96)
            ]
