        Chant(
            id: "ad_regias",
            groupID: "easter",
            latinTitle: "Ad Regias Agni Dapes",
            englishTitle: "At the Lamb's High Feast",
            setting: nil,
            detail: "The evening hymn of the Easter season",
            prayerIDs: [],
            duration: 220.1,
            score: [
                ChantScorePart(file: "chant-ad-regias-agni-dapes", caption: "Ad regias Agni dapes", aspectRatio: 0.5803)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/ad-regias-agni-dapes/")!,
            lines: [
                ChantLine(latin: "Ad régias Agni dapes,", english: "At the royal banquet of the Lamb,", start: 0.31, end: 6.81, part: 0),
                ChantLine(latin: "Stolis amícti cándidis,", english: "clothed in white robes,", start: 6.81, end: 12.48, part: 0),
                ChantLine(latin: "Post tránsitum maris Rubri, Christo canámus Príncipi.", english: "the Red Sea crossed, let us sing to Christ our Prince:", start: 13.03, end: 25.20, part: 0),
                ChantLine(latin: "Divína cujus cáritas Sacrum propínat sánguinem,", english: "whose divine charity gives us His sacred Blood to drink,", start: 26.41, end: 38.66, part: 0),
                ChantLine(latin: "Almíque membra córporis Amor sacérdos ímmolat.", english: "and Love, the priest, offers in sacrifice the members of His holy Body.", start: 39.07, end: 51.48, part: 0),
                ChantLine(latin: "Sparsum cruórem póstibus", english: "At the blood sprinkled on the doorposts", start: 52.25, end: 58.79, part: 0),
                ChantLine(latin: "Vastátor horret Ángelus:", english: "the destroying Angel shudders:", start: 58.79, end: 64.38, part: 0),
                ChantLine(latin: "Fugítque divísum mare, Mergúntur hostes flúctibus.", english: "the sea parts and flees; the enemies are drowned in the waves.", start: 64.97, end: 76.74, part: 0),
                ChantLine(latin: "Jam Pascha nostrum Christus est,", english: "Now Christ is our Pasch,", start: 78.15, end: 85.09, part: 0),
                ChantLine(latin: "Paschális idem víctima: Et pura puris méntibus Sinceritátis ázyma.", english: "and He the Paschal victim, and the pure unleavened bread of sincerity for pure minds.", start: 85.09, end: 103.48, part: 0),
                ChantLine(latin: "O vera cæli víctima, Subjécta cui sunt tártara,", english: "O true Victim from heaven, to whom hell is made subject,", start: 104.51, end: 117.35, part: 0),
                ChantLine(latin: "Solúta mortis víncula, Recépta vitæ prǽmia.", english: "the bonds of death are loosed, the rewards of life won back.", start: 117.35, end: 130.20, part: 0),
                ChantLine(latin: "Victor subáctis ínferis Tropǽa Christus éxplicat,", english: "Christ the victor, hell overthrown, displays His trophies,", start: 131.23, end: 143.75, part: 0),
                ChantLine(latin: "Cælóque apérto, súbditum Regem tenebrárum trahit.", english: "and, heaven opened, drags the king of darkness captive.", start: 143.75, end: 156.80, part: 0),
                ChantLine(latin: "Ut sis perénne méntibus Paschále Jesu gáudium,", english: "That Thou mayest be, O Jesus, an everlasting Paschal joy to our minds,", start: 157.09, end: 169.69, part: 0),
                ChantLine(latin: "A morte dira críminum Vitæ renátos líbera.", english: "free those reborn to life from the dread death of sin.", start: 169.69, end: 181.60, part: 0),
                ChantLine(latin: "Deo Patri sit glória, Et Fílio qui a mórtuis", english: "To God the Father be glory, and to the Son, who from the dead", start: 182.53, end: 194.84, part: 0),
                ChantLine(latin: "Surréxit, ac Paráclito, In sempitérna sǽcula.", english: "is risen, and to the Paraclete, for everlasting ages.", start: 194.89, end: 207.18, part: 0),
                ChantLine(latin: "Amen.", english: "Amen.", start: 208.01, end: 217.36, part: 0)
            ]
        ),
        Chant(
            id: "dies_irae",
            groupID: "departed",
            latinTitle: "Dies Iræ",
            englishTitle: "Day of Wrath",
            setting: nil,
            detail: "The poem sung at the funeral Mass, before the Gospel",
            prayerIDs: [],
            duration: 384.0,
            score: [
                ChantScorePart(file: "chant-dies-irae", caption: "Dies irae", aspectRatio: 0.2827)
            ],
            sourceURL: URL(string: "https://www.verbumgloriae.es/project/dies-irae/")!,
            lines: [
                ChantLine(latin: "Dies iræ, dies illa,", english: "The day of wrath, that day,", start: 0.53, end: 4.75),
                ChantLine(latin: "Solvet sæclum in favílla:", english: "shall dissolve the world in ashes,", start: 4.75, end: 10.63),
                ChantLine(latin: "Teste David cum Sibýlla.", english: "as David bears witness with the Sibyl.", start: 10.63, end: 17.18),
                ChantLine(latin: "Quantus tremor est futúrus,", english: "What trembling there shall be", start: 17.45, end: 21.97),
                ChantLine(latin: "Quando judex est ventúrus,", english: "when the Judge shall come", start: 21.97, end: 28.45),
                ChantLine(latin: "Cuncta stricte discussúrus!", english: "to sift all things strictly!", start: 28.45, end: 34.00),
                ChantLine(latin: "Tuba mirum spargens sonum", english: "The trumpet, scattering its wondrous sound", start: 34.55, end: 41.93),
                ChantLine(latin: "Per sepúlcra regiónum,", english: "through the tombs of every land,", start: 41.93, end: 46.67),
                ChantLine(latin: "Coget omnes ante thronum.", english: "shall gather all before the throne.", start: 46.67, end: 53.86),
                ChantLine(latin: "Mors stupébit et natúra,", english: "Death and nature shall stand amazed", start: 54.47, end: 61.97),
                ChantLine(latin: "Cum resúrget creatúra,", english: "when the creature shall rise again", start: 61.97, end: 66.49),
                ChantLine(latin: "Judicánti responsúra.", english: "to answer to its Judge.", start: 66.49, end: 74.10),
                ChantLine(latin: "Liber scriptus proferétur,", english: "The written book shall be brought forth,", start: 74.77, end: 81.99),
                ChantLine(latin: "In quo totum continétur,", english: "in which all is contained,", start: 81.99, end: 87.91),
                ChantLine(latin: "Unde mundus judicétur.", english: "whereby the world shall be judged.", start: 87.91, end: 93.94),
                ChantLine(latin: "Judex ergo cum sedébit,", english: "When therefore the Judge shall sit,", start: 95.01, end: 101.88),
                ChantLine(latin: "Quidquid latet apparébit:", english: "whatever is hidden shall appear;", start: 102.23, end: 107.60),
                ChantLine(latin: "Nil inúltum remanébit.", english: "nothing shall remain unavenged.", start: 108.15, end: 113.72),
                ChantLine(latin: "Quid sum miser tunc dictúrus?", english: "What shall I, wretch, say then?", start: 115.57, end: 120.09),
                ChantLine(latin: "Quem patrónum rogatúrus?", english: "What advocate shall I entreat,", start: 120.09, end: 126.13),
                ChantLine(latin: "Cum vix justus sit secúrus.", english: "when even the just is scarcely safe?", start: 126.13, end: 131.92),
                ChantLine(latin: "Rex treméndæ majestátis,", english: "King of dreadful majesty,", start: 132.81, end: 137.53),
                ChantLine(latin: "Qui salvándos salvas gratis,", english: "who freely savest those that are saved,", start: 137.53, end: 143.42),
                ChantLine(latin: "Salva me, fons pietátis.", english: "save me, O fount of pity.", start: 143.59, end: 149.26),
                ChantLine(latin: "Recordáre Jesu pie,", english: "Remember, loving Jesus,", start: 150.45, end: 158.05),
                ChantLine(latin: "Quod sum causa tuæ viæ:", english: "that I am the cause of Thy journey;", start: 158.05, end: 162.83),
                ChantLine(latin: "Ne me perdas illa die.", english: "lose me not on that day.", start: 162.83, end: 170.22),
                ChantLine(latin: "Quærens me, sedísti lassus:", english: "Seeking me, Thou didst sit down weary;", start: 171.11, end: 178.71),
                ChantLine(latin: "Redemísti crucem passus:", english: "Thou didst redeem me, suffering the Cross;", start: 178.71, end: 183.47),
                ChantLine(latin: "Tantus labor non sit cassus.", english: "let not such labour be in vain.", start: 183.47, end: 191.06),
                ChantLine(latin: "Juste judex ultiónis,", english: "Just Judge of vengeance,", start: 192.07, end: 198.97),
                ChantLine(latin: "Donum fac remissiónis,", english: "grant the gift of remission", start: 198.97, end: 204.42),
                ChantLine(latin: "Ante diem ratiónis.", english: "before the day of reckoning.", start: 204.91, end: 210.48),
                ChantLine(latin: "Ingemísco, tamquam reus:", english: "I groan as one guilty;", start: 212.27, end: 219.29),
                ChantLine(latin: "Culpa rubet vultus meus:", english: "my face blushes for my fault;", start: 219.29, end: 225.27),
                ChantLine(latin: "Supplicánti parce Deus.", english: "spare Thy suppliant, O God.", start: 225.27, end: 231.26),
                ChantLine(latin: "Qui Maríam absolvísti,", english: "Thou who didst absolve Mary", start: 232.37, end: 236.87),
                ChantLine(latin: "Et latrónem exaudísti,", english: "and didst hear the thief,", start: 236.87, end: 242.54),
                ChantLine(latin: "Mihi quoque spem dedísti.", english: "to me also hast given hope.", start: 242.89, end: 248.40),
                ChantLine(latin: "Preces meæ non sunt dignæ:", english: "My prayers are not worthy;", start: 249.55, end: 254.15),
                ChantLine(latin: "Sed tu bonus fac benígne,", english: "but Thou, who art good, deal kindly,", start: 254.15, end: 260.11),
                ChantLine(latin: "Ne perénni cremer igne.", english: "lest I burn in everlasting fire.", start: 260.11, end: 266.04),
                ChantLine(latin: "Inter oves locum præsta, Et ab hædis me sequéstra,", english: "Grant me a place among the sheep, and set me apart from the goats,", start: 266.63, end: 278.95),
                ChantLine(latin: "Státuens in parte dextra.", english: "placing me on Thy right hand.", start: 278.95, end: 286.74),
                ChantLine(latin: "Confutátis maledíctis,", english: "When the accursed are confounded", start: 287.15, end: 294.33),
                ChantLine(latin: "Flammis ácribus addíctis:", english: "and given over to the bitter flames,", start: 294.33, end: 298.98),
                ChantLine(latin: "Voca me cum benedíctis.", english: "call me with the blessed.", start: 299.03, end: 306.40),
                ChantLine(latin: "Oro supplex et acclínis,", english: "I pray, suppliant and bowed down,", start: 307.55, end: 314.58),
                ChantLine(latin: "Cor contrítum quasi cinis:", english: "my heart contrite as ashes:", start: 314.65, end: 320.20),
                ChantLine(latin: "Gere curam mei finis.", english: "take Thou care of my end.", start: 320.81, end: 326.18),
                ChantLine(latin: "Lacrimósa dies illa, Qua resúrget ex favílla,", english: "Tearful that day, when from the ashes shall rise", start: 328.09, end: 342.84),
                ChantLine(latin: "Judicándus homo reus:", english: "guilty man to be judged;", start: 343.21, end: 350.71),
                ChantLine(latin: "Huic ergo parce Deus.", english: "spare him therefore, O God.", start: 350.71, end: 360.30),
                ChantLine(latin: "Pie Jesu Dómine,", english: "Loving Lord Jesus,", start: 361.09, end: 365.61),
                ChantLine(latin: "dona eis réquiem.", english: "grant them rest.", start: 365.61, end: 371.88),
                ChantLine(latin: "Amen.", english: "Amen.", start: 372.43, end: 378.54)
            ]
        ),
