            lines: [
                ChantLine(latin: "Credo in unum Deum,", english: "I believe in one God,", start: 0.27, end: 5.40, part: 0),
                ChantLine(latin: "Patrem omnipoténtem,", english: "the Father almighty,", start: 6.15, end: 10.89, part: 0),
